import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) ʿaqīda: the Ashʿarī, Māturīdī and Atharī traditions, attributes and their interpretation, faith and takfīr, qadar, eschatology, early sects, kalām history and creedal works, framed as who held what. Draft content, needs scholarly review.
export const QS: RawQ[] = [
{ id: "xaq-001", s: "aqidah", g: 4, d: 6, t: ["schools", "ashari-maturidi-athari"], tr: ["sunni", "ashari", "maturidi", "athari"], src: "al-Shahrastānī, al-Milal wa-l-Niḥal; al-Subkī, Ṭabaqāt al-Shāfiʿiyya; Ibn Taymiyya, Majmūʿ al-Fatāwā; al-Ashʿarī, Maqālāt al-Islāmiyyīn",
    en: ["Which statement correctly describes the three main Sunni creedal traditions?", ["The Ashʿarīs follow Abū al-Ḥasan al-Ashʿarī (d. 324 AH), the Māturīdīs follow Abū Manṣūr al-Māturīdī (d. 333 AH) and the Atharīs (Ḥanbalī tradition) stress adherence to the transmitted texts and the way of the early generations", "All three follow the same founder", "The Ashʿarīs follow al-Māturīdī and the Māturīdīs follow Ibn Taymiyya", "They are the three Shīʿī schools"], "The three traditions are distinguished by method. The Ashʿarīs, originally with al-Ashʿarī’s turn from Muʿtazilism, use rational proofs alongside the texts; the Māturīdīs, based in Samarqand and followed by many Ḥanafīs, give more weight to reason on some questions; the Atharīs, associated with Aḥmad ibn Ḥanbal and later Ibn Taymiyya, stress the apparent text. All three are regarded as Ahl al-Sunna by their followers, with disputes over the boundaries."],
    de: ["Welche Aussage beschreibt die drei sunnitischen Glaubenstraditionen richtig?", ["Die Ašʿariten folgen Abū l-Ḥasan al-Ašʿarī (gest. 324 n. H.), die Māturīditen Abū Manṣūr al-Māturīdī (gest. 333 n. H.) und die Atharīten (ḥanbalitische Tradition) betonen das Festhalten an den überlieferten Texten und dem Weg der frühen Generationen", "Alle drei folgen demselben Gründer", "Die Ašʿariten folgen al-Māturīdī und die Māturīditen Ibn Taimiyya", "Es sind die drei schiitischen Schulen"], "Die drei Traditionen unterscheiden sich in der Methode. Die Ašʿariten, ursprünglich mit al-Ašʿarīs Abkehr vom Muʿtazilismus, gebrauchen verstandesmäßige Beweise neben den Texten; die Māturīditen, in Samarkand beheimatet und von vielen Ḥanafiten befolgt, geben dem Verstand in manchen Fragen mehr Gewicht; die Atharīten, mit Aḥmad ibn Ḥanbal und später Ibn Taimiyya verbunden, betonen den offenkundigen Text. Alle drei gelten ihren Anhängern als Ahl as-Sunna, mit Streit über die Grenzen."],
    ar: ["أي عبارة تصف التقاليد العقدية السنية الثلاثة الرئيسة على الوجه الصحيح؟", ["الأشاعرة يتبعون أبا الحسن الأشعري (ت 324هـ) والماتريدية يتبعون أبا منصور الماتريدي (ت 333هـ) وأهل الأثر (التقليد الحنبلي) يشددون على التمسك بالنصوص المنقولة وطريقة السلف", "الثلاثة يتبعون مؤسسًا واحدًا", "الأشاعرة يتبعون الماتريدي والماتريدية يتبعون ابن تيمية", "هي المذاهب الشيعية الثلاثة"], "تتميز التقاليد الثلاثة بالمنهج: الأشاعرة، وأصلهم رجوع الأشعري عن الاعتزال، يستعملون الأدلة العقلية مع النصوص، والماتريدية وموطنهم سمرقند ويتبعهم كثير من الحنفية يعطون العقل وزنًا أكبر في بعض المسائل، وأهل الأثر وينسبون إلى أحمد بن حنبل ثم ابن تيمية يؤكدون ظاهر النص، وكلها تُعد من أهل السنة عند أتباعها مع خلاف في الحدود."] },

  { id: "xaq-002", s: "aqidah", g: 4, d: 7, t: ["attributes", "seven-attributes", "ashari"], tr: ["ashari", "maturidi", "athari"], src: "al-Sanūsī, Umm al-Barāhīn; al-Bayjūrī, Tuḥfat al-Murīd; al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya",
    en: ["How do Ashʿarī and Māturīdī manuals differ in counting the attributes of God proved by reason?", ["The Ashʿarī manuals count seven essential attributes (life, knowledge, power, will, hearing, sight, speech), while the Māturīdīs add takwīn (creating) as a separate attribute", "Ashʿarīs count only one attribute", "Both reject any attribute", "Māturīdīs count three, Ashʿarīs thirty"], "Ashʿarī works such as al-Sanūsī’s Umm al-Barāhīn list seven attributes of meaning (ṣifāt al-maʿānī): ḥayāt, ʿilm, qudra, irāda, samʿ, baṣar and kalām. The Māturīdīs affirm the same and add takwīn (bringing into being), which the Ashʿarīs include under power. The Atharīs affirm what the texts affirm without limiting to a fixed number."],
    de: ["Wie unterscheiden sich ašʿaritische und māturiditische Handbücher bei der Zählung der durch Vernunft bewiesenen Attribute Gottes?", ["Die ašʿaritischen Handbücher zählen sieben Wesensattribute (Leben, Wissen, Macht, Wille, Hören, Sehen, Sprache), die Māturīditen fügen takwīn (Schaffen) als eigenes Attribut hinzu", "Die Ašʿariten zählen nur ein Attribut", "Beide lehnen jedes Attribut ab", "Die Māturīditen zählen drei, die Ašʿariten dreißig"], "Ašʿaritische Werke wie as-Sanūsīs Umm al-Barāhīn zählen sieben Sinnattribute (ṣifāt al-maʿānī): ḥayāt, ʿilm, qudra, irāda, samʿ, baṣar und kalām. Die Māturīditen bejahen dasselbe und fügen takwīn (ins Dasein bringen) hinzu, das die Ašʿariten unter der Macht einordnen. Die Atharīten bejahen, was die Texte bejahen, ohne auf eine feste Zahl zu beschränken."],
    ar: ["كيف تختلف كتب الأشاعرة والماتريدية في عدّ صفات الله الثابتة بالعقل؟", ["تعد كتب الأشاعرة سبع صفات معنوية (الحياة والعلم والقدرة والإرادة والسمع والبصر والكلام) ويزيد الماتريدية التكوين صفة مستقلة", "يعد الأشاعرة صفة واحدة فقط", "كلاهما ينكر كل صفة", "يعد الماتريدية ثلاثًا والأشاعرة ثلاثين"], "تعد كتب الأشاعرة كـ«أم البراهين» للسنوسي سبع صفات المعاني: الحياة والعلم والقدرة والإرادة والسمع والبصر والكلام، ويثبت الماتريدية الصفات نفسها ويزيدون التكوين الذي يدخله الأشاعرة في القدرة، ويثبت أهل الأثر ما أثبتته النصوص دون حصر بعدد."] },

  { id: "xaq-003", s: "aqidah", g: 4, d: 7, t: ["attributes", "kalam-nafsi", "quran-uncreated"], tr: ["ashari", "athari", "maturidi"], src: "al-Ashʿarī, al-Ibāna ʿan Uṣūl al-Diyāna; al-Bayhaqī, al-Asmāʾ wa-l-Ṣifāt; Ibn Taymiyya, Majmūʿ al-Fatāwā; al-Juwaynī, al-Irshād",
    en: ["How did the traditions explain that the Quran is not created while it is recited, written and heard?", ["The Ashʿarīs and Māturīdīs distinguish the inner speech of God (al-kalām al-nafsī), which is eternal, from the recited words, which are created as sounds; the Atharīs held the Quran to be God’s speech, uncreated, in letter and sound, and disliked saying that the recitation is created", "All traditions say the Quran is created", "All traditions say the ink is eternal", "Nobody discussed it"], "The controversy about the Quran’s createdness (the miḥna under al-Maʾmūn, with Aḥmad ibn Ḥanbal’s resistance) led to doctrinal formulas. The Ashʿarīs say the Quran as God’s speech is eternal, while the readings and writing are created in the sense of the reciter’s acts; the Māturīdīs say similarly. Ahl al-Athar, with Aḥmad, held that the Quran is God’s speech, uncreated, and rejected statements on the recitation (lafẓ) either way."],
    de: ["Wie erklärten die Traditionen, dass der Koran nicht erschaffen ist, obwohl er rezitiert, geschrieben und gehört wird?", ["Die Ašʿariten und Māturīditen unterscheiden die innere Rede Gottes (al-kalām an-nafsī), die ewig ist, von den rezitierten Wörtern, die als Laute erschaffen sind; die Atharīten hielten den Koran für Gottes Rede, unerschaffen, in Buchstabe und Laut, und mochten nicht sagen, die Rezitation sei erschaffen", "Alle Traditionen sagen, der Koran sei erschaffen", "Alle Traditionen sagen, die Tinte sei ewig", "Niemand erörterte es"], "Der Streit um die Erschaffenheit des Korans (die Miḥna unter al-Maʾmūn, mit Aḥmad ibn Ḥanbals Widerstand) führte zu Lehrformeln. Die Ašʿariten sagen, der Koran als Gottes Rede sei ewig, während Lesungen und Schrift erschaffen seien im Sinne der Handlungen des Rezitierenden; die Māturīditen sagen Ähnliches. Die Ahl al-Aṯar mit Aḥmad hielten, der Koran sei Gottes Rede, unerschaffen, und lehnten Aussagen über die Rezitation (lafẓ) in beide Richtungen ab."],
    ar: ["كيف فسّرت التقاليد العقدية أن القرآن غير مخلوق مع أنه يُتلى ويُكتب ويُسمع؟", ["يفرق الأشاعرة والماتريدية بين كلام الله النفسي القديم والألفاظ المتلوة المخلوقة صوتًا، وقال أهل الأثر إن القرآن كلام الله غير مخلوق بحرفه وصوته وكرهوا القول بأن اللفظ بالقرآن مخلوق", "كل التقاليد تقول إن القرآن مخلوق", "كل التقاليد تقول إن الحبر قديم", "لم يبحثه أحد"], "أدى خلاف خلق القرآن (المحنة في عهد المأمون وصبر أحمد بن حنبل) إلى صيغ عقدية: يقول الأشاعرة إن القرآن بوصفه كلام الله قديم، والتلاوة والكتابة مخلوقة بمعنى أفعال العباد، ويقول الماتريدية نحوه، ويرى أهل الأثر مع أحمد أنه كلام الله غير مخلوق، وينكرون الخوض في اللفظ نفيًا أو إثباتًا."] },

  { id: "xaq-004", s: "aqidah", g: 4, d: 7, t: ["attributes", "tafwid-taawil", "mutashabih"], tr: ["athari", "ashari", "comparative"], src: "al-Juwaynī, al-ʿAqīda al-Niẓāmiyya; Ibn Qudāma, Lumʿat al-Iʿtiqād; Ibn Taymiyya, al-Tadmuriyya; al-Bayhaqī, al-Asmāʾ wa-l-Ṣifāt",
    en: ["How do the traditions differ in dealing with the apparent attributes of God such as ‘hand’ and ‘face’ (ṣifāt khabariyya)?", ["The Atharīs affirm them as they came without asking how (bi-lā kayf) and without likeness; many early Ashʿarīs favoured delegating the meaning (tafwīḍ), while later Ashʿarīs and Māturīdīs often allowed figurative interpretation (taʾwīl)", "All traditions interpret them as bodily limbs", "All traditions reject any mention of them", "All traditions ignore them"], "The texts of Quran and Sunna mention God’s face, hand, eye and ascension above the throne. The Atharīs, with Ibn Qudāma and Ibn Taymiyya, affirm them as befits God without likening or asking how. Al-Juwaynī in al-ʿAqīda al-Niẓāmiyya reports the way of the early generations as delegation (tafwīḍ), and later Ashʿarīs, such as al-Rāzī and Ibn Fūrak, gave figurative readings, for instance interpreting ‘hand’ as power. The traditions disagree about which approach is that of the early Muslims."],
    de: ["Wie unterscheiden sich die Traditionen im Umgang mit den offenkundigen Attributen Gottes wie ‚Hand‘ und ‚Gesicht‘ (ṣifāt ḫabariyya)?", ["Die Atharīten bejahen sie, wie sie kamen, ohne zu fragen wie (bi-lā kaif) und ohne Vergleich; viele frühe Ašʿariten bevorzugten die Überlassung der Bedeutung (tafwīḍ), während spätere Ašʿariten und Māturīditen oft figürliche Auslegung (taʾwīl) erlaubten", "Alle Traditionen deuten sie als körperliche Glieder", "Alle Traditionen lehnen jede Erwähnung ab", "Alle Traditionen ignorieren sie"], "Die Texte von Koran und Sunna erwähnen Gottes Gesicht, Hand, Auge und das Erheben über den Thron. Die Atharīten mit Ibn Qudāma und Ibn Taimiyya bejahen sie, wie es Gott gebührt, ohne Vergleich und ohne Frage nach dem Wie. Al-Ǧuwainī berichtet in al-ʿAqīda an-Niẓāmiyya den Weg der frühen Generationen als Überlassung (tafwīḍ), und spätere Ašʿariten wie ar-Rāzī und Ibn Fūrak gaben figürliche Lesungen, etwa die Deutung von ‚Hand‘ als Macht. Die Traditionen sind uneins, welcher Ansatz der der frühen Muslime ist."],
    ar: ["كيف تختلف التقاليد العقدية في التعامل مع الصفات الخبرية كاليد والوجه؟", ["يثبتها أهل الأثر كما جاءت بلا كيف ولا تشبيه، وفضّل كثير من الأشاعرة الأوائل التفويض، وأجاز متأخرو الأشاعرة والماتريدية غالبًا التأويل", "تفسرها كل التقاليد أعضاءً جسمية", "ترفض كل التقاليد ذكرها", "تتجاهلها كل التقاليد"], "ورد في الكتاب والسنة ذكر وجه الله ويده وعينه واستواؤه على العرش، فيثبتها أهل الأثر كابن قدامة وابن تيمية على ما يليق بالله دون تشبيه ولا سؤال عن الكيفية، وحكى الجويني في «العقيدة النظامية» أن طريقة السلف التفويض، وأوّل متأخرو الأشاعرة كالرازي وابن فورك فحملوا اليد مثلًا على القدرة، وتختلف التقاليد في أي الطريقين هو طريق السلف."] },

  { id: "xaq-005", s: "aqidah", g: 4, d: 6, t: ["tawhid", "three-divisions"], tr: ["athari", "comparative"], src: "Ibn Taymiyya, Majmūʿ al-Fatāwā; Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya; al-Ṭabarī and Ibn Manda (early uses)",
    en: ["What are the three categories of tawḥīd as taught in the Atharī tradition, and how do other traditions regard the division?", ["Tawḥīd al-rubūbiyya, al-ulūhiyya and al-asmāʾ wa-l-ṣifāt, a classification later associated with Ibn Taymiyya and Ibn Abī al-ʿIzz; other scholars accept the content but not always the division as a method", "Tawḥīd of men, women and children", "Tawḥīd of the heart, the tongue and the limbs only, rejected by all", "Tawḥīd of the East, the West and the South"], "The threefold division of tawḥīd (lordship, divinity and names and attributes) is used in the Atharī/Salafī tradition, citing early scholars such as Ibn Manda and developed by Ibn Taymiyya. Ashʿarīs and Māturīdīs describe tawḥīd by the oneness of essence, attributes and acts, and some scholars object that the three-part scheme was not used by the early generations, while its defenders say it reflects the texts."],
    de: ["Welche drei Kategorien des Tauḥīd lehrt die Atharī-Tradition, und wie sehen andere Traditionen die Einteilung?", ["Tauḥīd ar-rubūbiyya, al-ulūhiyya und al-asmāʾ wa-ṣ-ṣifāt, eine später mit Ibn Taimiyya und Ibn Abī l-ʿIzz verbundene Einteilung; andere Gelehrte akzeptieren den Inhalt, aber nicht immer die Einteilung als Methode", "Tauḥīd der Männer, Frauen und Kinder", "Tauḥīd des Herzens, der Zunge und der Glieder allein, von allen abgelehnt", "Tauḥīd des Ostens, Westens und Südens"], "Die dreifache Einteilung des Tauḥīd (Herrschaft, Gottheit sowie Namen und Attribute) wird in der Atharī/Salafī-Tradition gebraucht, unter Berufung auf frühe Gelehrte wie Ibn Manda, und von Ibn Taimiyya ausgebaut. Ašʿariten und Māturīditen beschreiben den Tauḥīd durch die Einheit von Wesen, Attributen und Handlungen, und manche Gelehrte wenden ein, das Dreierschema sei von den frühen Generationen nicht gebraucht worden, während seine Verteidiger sagen, es spiegle die Texte."],
    ar: ["ما أقسام التوحيد الثلاثة في التقليد الأثري وكيف تنظر التقاليد الأخرى إلى هذا التقسيم؟", ["توحيد الربوبية والألوهية والأسماء والصفات، وهو تقسيم ارتبط لاحقًا بابن تيمية وابن أبي العز، ويقبل غيرهم المضمون دون التقسيم منهجًا دائمًا", "توحيد الرجال والنساء والأطفال", "توحيد القلب واللسان والجوارح فقط ويرفضه الجميع", "توحيد الشرق والغرب والجنوب"], "يستعمل التقليد الأثري والسلفي التقسيم الثلاثي للتوحيد (الربوبية والألوهية والأسماء والصفات) محتجًّا بكلام متقدمين كابن منده وطوّره ابن تيمية، ويصف الأشاعرة والماتريدية التوحيد بوحدانية الذات والصفات والأفعال، ويعترض بعضهم بأن هذا التقسيم لم يُعرف عن السلف، ويرد المدافعون بأنه مستنبط من النصوص."] },

  { id: "xaq-006", s: "aqidah", g: 4, d: 7, t: ["faith", "iman-definition", "murjia"], tr: ["comparative", "athari", "ashari", "maturidi", "hanafi"], src: "Abū Ḥanīfa, al-Fiqh al-Akbar; al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya; al-Bukhārī, Ṣaḥīḥ, Kitāb al-īmān; Ibn Abī al-ʿIzz, Sharḥ al-Ṭaḥāwiyya",
    en: ["How did the traditions define īmān, and does it increase and decrease?", ["The Atharīs define īmān as speech, action and belief, increasing and decreasing; the Ḥanafī/Māturīdī tradition (Abū Ḥanīfa) defined it as affirmation with the tongue and assent of the heart, with works outside it, and denied increase and decrease in its core; many Ashʿarīs allowed increase in some reports", "All traditions define faith as only an utterance", "All traditions deny any definition", "All traditions say faith is only works"], "Atharī scholars, with al-Bukhārī, included works in faith, and said it rises with obedience and falls with sin. Abū Ḥanīfa held that works are not part of faith itself, so that the faith of people is equal in its essence, which the Atharīs called irjāʾ; his school responded that the dispute is largely verbal as both agree that sins damage a believer and works are required. Ashʿarīs differ: some allow increase and decrease through its effects."],
    de: ["Wie definierten die Traditionen Īmān, und nimmt er zu und ab?", ["Die Atharīten definieren Īmān als Rede, Handlung und Überzeugung, zunehmend und abnehmend; die ḥanafitisch-māturiditische Tradition (Abū Ḥanīfa) definierte ihn als Bekenntnis mit der Zunge und Zustimmung des Herzens, wobei Werke außerhalb stehen, und verneinte Zunahme und Abnahme im Kern; viele Ašʿariten erlaubten Zunahme in manchen Berichten", "Alle Traditionen definieren Glauben nur als Äußerung", "Alle Traditionen verneinen jede Definition", "Alle Traditionen sagen, Glaube sei nur Werke"], "Atharī-Gelehrte, mit al-Buḫārī, schlossen Werke in den Glauben ein und sagten, er steige mit Gehorsam und sinke mit Sünde. Abū Ḥanīfa hielt, Werke seien nicht Teil des Glaubens selbst, sodass der Glaube der Menschen im Wesen gleich sei, was die Atharīten Irǧāʾ nannten; seine Schule antwortete, der Streit sei weitgehend verbal, da beide einig seien, dass Sünden einen Gläubigen schädigen und Werke verlangt werden. Die Ašʿariten sind uneins: manche erlauben Zunahme und Abnahme durch seine Wirkungen."],
    ar: ["كيف عرفت التقاليد العقدية الإيمان وهل يزيد وينقص؟", ["عرفه أهل الأثر بقول وعمل واعتقاد يزيد وينقص، وعرفه الحنفية الماتريدية (أبو حنيفة) بالإقرار باللسان والتصديق بالقلب والأعمال خارجة عنه وأنكروا الزيادة والنقصان في أصله، وأجاز كثير من الأشاعرة الزيادة في بعض الروايات", "كل التقاليد تعرفه بالقول فقط", "كل التقاليد تنفي أي تعريف", "كل التقاليد تقول إنه أعمال فقط"], "أدخل علماء الأثر ومنهم البخاري الأعمال في الإيمان وقالوا يزيد بالطاعة وينقص بالمعصية، وذهب أبو حنيفة إلى أن الأعمال ليست من الإيمان نفسه فإيمان الناس متساوٍ في أصله وسمّى الأثريون ذلك إرجاءً، وأجاب الحنفية بأن الخلاف لفظي في الغالب إذ الجميع يرى أن المعصية تضر المؤمن وأن الأعمال مطلوبة، ويختلف الأشاعرة فمنهم من أجاز الزيادة والنقصان في آثاره."] },

  { id: "xaq-007", s: "aqidah", g: 4, d: 6, t: ["faith", "istithna", "i-am-a-believer-god-willing"], tr: ["athari", "hanafi", "ashari", "comparative"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya; Ibn Abī al-ʿIzz, Sharḥ al-Ṭaḥāwiyya; al-Bayhaqī, Shuʿab al-Īmān",
    en: ["What is the debate on saying 'I am a believer, if God wills' (al-istithnāʾ fī al-īmān)?", ["Many Atharīs and Shāfiʿīs allowed it out of humility or doubt about the final outcome, while the Ḥanafīs generally disliked it as implying doubt in present faith", "All traditions required it", "All traditions forbade any mention of God’s will", "Nobody discussed it"], "The question divided early scholars. Those who allowed it, such as many Atharīs and Shāfiʿīs, meant uncertainty about one’s final state or humility, not doubt about present assent. The Ḥanafīs, and Abū Ḥanīfa in a report, rejected it, saying it expresses doubt, and preferred ‘I am a believer in truth’. Some, like al-Ṭaḥāwī, discussed the permissible meanings."],
    de: ["Was ist die Debatte über den Satz ‚Ich bin ein Gläubiger, so Gott will‘ (al-istiṯnāʾ fī l-īmān)?", ["Viele Atharīten und Šāfiʿiten erlaubten ihn aus Demut oder Zweifel am Ausgang, während die Ḥanafiten ihn im Allgemeinen als Ausdruck von Zweifel am gegenwärtigen Glauben missbilligten", "Alle Traditionen verlangten ihn", "Alle Traditionen verboten jede Erwähnung von Gottes Willen", "Niemand erörterte ihn"], "Die Frage spaltete frühe Gelehrte. Die ihn erlaubten, wie viele Atharīten und Šāfiʿiten, meinten Unsicherheit über den endgültigen Zustand oder Demut, nicht Zweifel an der gegenwärtigen Zustimmung. Die Ḥanafiten und Abū Ḥanīfa nach einem Bericht lehnten ihn ab, da er Zweifel ausdrücke, und bevorzugten ‚Ich bin in Wahrheit ein Gläubiger‘. Manche wie aṭ-Ṭaḥāwī erörterten die zulässigen Bedeutungen."],
    ar: ["ما الخلاف في قول «أنا مؤمن إن شاء الله» (الاستثناء في الإيمان)؟", ["أجازه كثير من أهل الأثر والشافعية تواضعًا أو خوف العاقبة، وكرهه الحنفية عمومًا لإيهامه الشك في الإيمان الحاضر", "أوجبته كل التقاليد", "منعت كل التقاليد ذكر مشيئة الله", "لم يبحثه أحد"], "انقسم المتقدمون في المسألة، ومن أجازه كأكثر أهل الأثر والشافعية قصد عدم الجزم بالعاقبة أو التواضع لا الشك في التصديق الحاضر، ورفضه الحنفية ويُروى عن أبي حنيفة لأنه يوهم الشك وفضّلوا «أنا مؤمن حقًّا»، وتناول الطحاوي وغيره المعاني الجائزة."] },

  { id: "xaq-008", s: "aqidah", g: 4, d: 7, t: ["takfir", "ahl-al-qibla", "conditions"], tr: ["sunni", "comparative"], src: "al-Ghazālī, Fayṣal al-Tafriqa bayna al-Islām wa-l-Zandaqa; Ibn Taymiyya, Majmūʿ al-Fatāwā; al-Shawkānī, al-Sayl al-Jarrār; al-Ṭaḥāwī, al-ʿAqīda",
    en: ["What general principle about takfīr (declaring a Muslim an unbeliever) is stated in the classical creeds?", ["That Ahl al-Qibla are not declared unbelievers for sins, and takfīr of a person requires conditions (knowledge, absence of coercion, removal of doubt) and an authorised judgment, as stressed by al-Ghazālī and Ibn Taymiyya", "That any Muslim may declare another an unbeliever freely", "That takfīr is the first duty of faith", "That takfīr applies to anyone who has a different school"], "Al-Ṭaḥāwī and others write that we do not declare any of Ahl al-Qibla unbelievers for a sin so long as he does not deem it lawful. Al-Ghazālī in Fayṣal al-Tafriqa warned against hastiness in takfīr and limited it to denial of what is known to be of the religion by necessity. Ibn Taymiyya distinguished the ruling on a statement from the ruling on the speaker, who must have knowledge and no excuse."],
    de: ["Welcher allgemeine Grundsatz zum Takfīr (Erklärung eines Muslims zum Ungläubigen) steht in den klassischen Glaubensbekenntnissen?", ["Dass Ahl al-Qibla nicht wegen Sünden für ungläubig erklärt werden und der Takfīr einer Person Bedingungen (Wissen, Fehlen von Zwang, Ausräumen von Zweifel) und ein befugtes Urteil verlangt, wie al-Ġazālī und Ibn Taimiyya betonen", "Dass jeder Muslim einen anderen frei für ungläubig erklären darf", "Dass der Takfīr die erste Pflicht des Glaubens ist", "Dass der Takfīr auf jeden mit anderer Rechtsschule zutrifft"], "Aṭ-Ṭaḥāwī und andere schreiben, wir erklärten keinen von Ahl al-Qibla wegen einer Sünde für ungläubig, solange er sie nicht für erlaubt hält. Al-Ġazālī warnte in Faiṣal at-Tafriqa vor Voreiligkeit beim Takfīr und beschränkte ihn auf die Leugnung dessen, was notwendigerweise als zur Religion gehörig bekannt ist. Ibn Taimiyya unterschied das Urteil über eine Aussage vom Urteil über den Sprecher, der Wissen haben muss und keine Entschuldigung."],
    ar: ["ما المبدأ العام في التكفير الوارد في العقائد الكلاسيكية؟", ["أن أهل القبلة لا يُكفّرون بذنب، وأن تكفير الشخص يتطلب شروطًا (العلم وانتفاء الإكراه وإزالة الشبهة) وحكمًا معتبرًا كما شدد الغزالي وابن تيمية", "أن لكل مسلم أن يكفّر غيره بحرية", "أن التكفير أول واجبات الإيمان", "أن التكفير يطبق على كل من خالف المذهب"], "قال الطحاوي وغيره إنهم لا يكفّرون أحدًا من أهل القبلة بذنب ما لم يستحله، وحذر الغزالي في «فيصل التفرقة» من التسرع في التكفير وقصره على إنكار ما عُلم من الدين بالضرورة، وفرق ابن تيمية بين الحكم على القول والحكم على القائل الذي يشترط علمه وانتفاء عذره."] },

  { id: "xaq-009", s: "aqidah", g: 4, d: 7, t: ["qadar", "kasb", "ashari-maturidi"], tr: ["ashari", "maturidi", "athari", "comparative"], src: "al-Ashʿarī, al-Lumaʿ; al-Māturīdī, Kitāb al-Tawḥīd; al-Ṭaḥāwī, al-ʿAqīda; Ibn Taymiyya, Minhāj al-Sunna",
    en: ["How did the traditions explain human acts and God’s creation of them (kasb and ikhtiyār)?", ["Al-Ashʿarī taught that God creates the act and the servant acquires (kasb) it; the Māturīdīs gave the servant a real choice (ikhtiyār) in directing the created power; the Atharīs affirmed God’s creation of acts and the servant’s will and ability without elaborate theory", "All traditions say humans create their acts independently", "All traditions say humans have no will whatsoever", "Nobody discussed human acts"], "The Muʿtazila held that humans create their acts. The Sunni traditions affirmed God’s creation of all things, including acts, while preserving responsibility. The Ashʿarī theory of kasb says that the act is created by God and acquired by the servant; the Māturīdīs say that the servant’s choice is real and is the ground for accountability; the Atharīs state that humans have will and ability and God is Creator of both, without a formal theory."],
    de: ["Wie erklärten die Traditionen menschliche Handlungen und Gottes Schaffen derselben (kasb und iḫtiyār)?", ["Al-Ašʿarī lehrte, Gott schaffe die Handlung und der Diener erwerbe (kasb) sie; die Māturīditen gaben dem Diener eine wirkliche Wahl (iḫtiyār) bei der Lenkung der geschaffenen Kraft; die Atharīten bejahten Gottes Schaffen der Handlungen und Willen und Fähigkeit des Dieners ohne ausgefeilte Theorie", "Alle Traditionen sagen, Menschen schaffen ihre Handlungen unabhängig", "Alle Traditionen sagen, Menschen hätten überhaupt keinen Willen", "Niemand erörterte menschliche Handlungen"], "Die Muʿtazila hielten, Menschen schüfen ihre Handlungen. Die sunnitischen Traditionen bejahten Gottes Schaffen aller Dinge einschließlich der Handlungen, wahrten aber die Verantwortung. Die ašʿaritische Kasb-Theorie sagt, die Handlung werde von Gott geschaffen und vom Diener erworben; die Māturīditen sagen, die Wahl des Dieners sei wirklich und Grundlage der Verantwortlichkeit; die Atharīten stellen fest, dass Menschen Willen und Fähigkeit haben und Gott Schöpfer beider ist, ohne förmliche Theorie."],
    ar: ["كيف فسّرت التقاليد العقدية أفعال العباد وخلق الله لها (الكسب والاختيار)؟", ["علّم الأشعري أن الله يخلق الفعل والعبد يكسبه، وأعطى الماتريدية العبد اختيارًا حقيقيًّا في توجيه القدرة المخلوقة، وأثبت أهل الأثر خلق الله للأفعال وإرادة العبد وقدرته دون نظرية مفصلة", "كل التقاليد تقول إن الناس يخلقون أفعالهم باستقلال", "كل التقاليد تقول إن الناس لا إرادة لهم", "لم يبحث أحد أفعال العباد"], "قال المعتزلة إن العباد يخلقون أفعالهم، وأثبتت التقاليد السنية خلق الله لكل شيء ومنه الأفعال مع بقاء المسؤولية، ونظرية الكسب عند الأشاعرة أن الفعل يخلقه الله ويكسبه العبد، ويرى الماتريدية أن اختيار العبد حقيقي وهو مناط التكليف، ويقرر أهل الأثر أن للعبد مشيئة وقدرة والله خالقهما دون نظرية منظمة."] },

  { id: "xaq-010", s: "aqidah", g: 4, d: 6, t: ["qadar", "early-qadariyya", "mabad-al-juhani"], src: "Muslim, Ṣaḥīḥ, Kitāb al-īmān (ḥadīth ʿUmar on Jibrīl); al-Dhahabī, Mīzān al-Iʿtidāl; al-Shahrastānī, al-Milal wa-l-Niḥal",
    en: ["Who is named as the first to speak of denying qadar in Islam, according to the account of Yaḥyā ibn Yaʿmar in Muslim?", ["Maʿbad al-Juhanī in Baṣra, as Yaḥyā ibn Yaʿmar and Ḥumayd al-Ḥimyarī reported to ʿAbd Allāh ibn ʿUmar", "Al-Ashʿarī in Baghdad", "Ibn Taymiyya in Damascus", "Abū Ḥanīfa in Kūfa"], "Muslim opens Kitāb al-īmān with the account of Yaḥyā ibn Yaʿmar, who told Ibn ʿUmar that people in Baṣra denied qadar and claimed that matters are unforeseen; Ibn ʿUmar disowned them and related the ḥadīth of ʿUmar on Jibrīl. Maʿbad al-Juhanī is named as the first to speak so in Baṣra, later executed in the time of ʿAbd al-Malik ibn Marwān according to the sources."],
    de: ["Wer wird nach dem Bericht von Yaḥyā ibn Yaʿmar bei Muslim als der Erste genannt, der im Islam die Leugnung des Qadar vertrat?", ["Maʿbad al-Ǧuhanī in Basra, wie Yaḥyā ibn Yaʿmar und Ḥumaid al-Ḥimyarī ʿAbd Allāh ibn ʿUmar berichteten", "Al-Ašʿarī in Bagdad", "Ibn Taimiyya in Damaskus", "Abū Ḥanīfa in Kufa"], "Muslim eröffnet das Kitāb al-īmān mit dem Bericht von Yaḥyā ibn Yaʿmar, der Ibn ʿUmar sagte, in Basra leugneten Leute den Qadar und behaupteten, die Dinge seien unvorhergesehen; Ibn ʿUmar sagte sich von ihnen los und überlieferte den Hadith ʿUmars über Ǧibrīl. Maʿbad al-Ǧuhanī wird als der Erste genannt, der in Basra so sprach, und wurde nach den Quellen zur Zeit ʿAbd al-Maliks ibn Marwān hingerichtet."],
    ar: ["من الذي يُذكر أول من تكلم بنفي القدر في الإسلام بحسب خبر يحيى بن يعمر في مسلم؟", ["معبد الجهني في البصرة كما أخبر يحيى بن يعمر وحميد الحميري عبد الله بن عمر", "الأشعري في بغداد", "ابن تيمية في دمشق", "أبو حنيفة في الكوفة"], "يفتتح مسلم كتاب الإيمان بخبر يحيى بن يعمر الذي أخبر ابن عمر أن ناسًا في البصرة ينكرون القدر ويزعمون أن الأمر أنف، فتبرأ منهم ابن عمر وروى حديث عمر في جبريل، ويُذكر معبد الجهني أول من تكلم بذلك في البصرة وقُتل في عهد عبد الملك بن مروان بحسب المصادر."] },

  { id: "xaq-011", s: "aqidah", g: 4, d: 7, t: ["qadar", "hidaya-dalala", "legislative-will"], tr: ["comparative", "ashari", "maturidi", "athari"], src: "Ibn Taymiyya, Majmūʿ al-Fatāwā; Ibn al-Qayyim, Shifāʾ al-ʿAlīl; al-Māturīdī, Kitāb al-Tawḥīd; al-Ashʿarī, al-Lumaʿ",
    en: ["How do the traditions relate God’s will (irāda) to His command (amr)?", ["Ashʿarīs hold that God’s will includes everything that occurs, even disobedience, and that command is separate from will; Māturīdīs similarly distinguish God’s will from His pleasure and love; Atharīs such as Ibn Taymiyya and Ibn al-Qayyim distinguish the creative will (kawniyya) from the legislative will (sharʿiyya)", "All traditions say will and command are always identical", "All traditions say God has no will", "All traditions say will applies only to obedience"], "The Muʿtazila held that God does not will evil, only commands good. The Sunni traditions affirm that nothing occurs but by God’s will, yet He does not love or command evil. Ashʿarīs and Māturīdīs distinguish will from pleasure and love; Ibn Taymiyya and Ibn al-Qayyim distinguish two kinds of will, the creative (what occurs) and the legislative (what God loves and commands), to explain how disobedience occurs by His will yet against His command."],
    de: ["Wie setzen die Traditionen Gottes Willen (irāda) zu Seinem Befehl (amr) in Beziehung?", ["Ašʿariten halten, Gottes Wille umfasse alles Geschehende, auch Ungehorsam, und der Befehl sei vom Willen getrennt; Māturīditen unterscheiden ebenso Gottes Willen von Seinem Wohlgefallen und Seiner Liebe; Atharīten wie Ibn Taimiyya und Ibn al-Qayyim unterscheiden den schöpferischen Willen (kauniyya) vom gesetzgebenden Willen (šarʿiyya)", "Alle Traditionen sagen, Wille und Befehl seien stets identisch", "Alle Traditionen sagen, Gott habe keinen Willen", "Alle Traditionen sagen, der Wille beziehe sich nur auf Gehorsam"], "Die Muʿtazila hielten, Gott wolle nicht das Böse, sondern befehle nur das Gute. Die sunnitischen Traditionen bejahen, dass nichts geschieht außer durch Gottes Willen, doch Er liebt oder befiehlt das Böse nicht. Ašʿariten und Māturīditen unterscheiden Wille von Wohlgefallen und Liebe; Ibn Taimiyya und Ibn al-Qayyim unterscheiden zwei Arten von Willen, den schöpferischen (was geschieht) und den gesetzgebenden (was Gott liebt und befiehlt), um zu erklären, wie Ungehorsam nach Seinem Willen und doch gegen Seinen Befehl geschieht."],
    ar: ["كيف تربط التقاليد العقدية بين إرادة الله وأمره؟", ["يرى الأشاعرة أن إرادة الله تشمل كل ما يقع حتى المعصية وأن الأمر غير الإرادة، ويفرق الماتريدية بين الإرادة والرضا والمحبة، ويميز ابن تيمية وابن القيم من أهل الأثر الإرادة الكونية من الإرادة الشرعية", "كل التقاليد تقول إن الإرادة والأمر متطابقان دائمًا", "كل التقاليد تقول إن الله لا إرادة له", "كل التقاليد تقول إن الإرادة في الطاعة فقط"], "قال المعتزلة إن الله لا يريد الشر وإنما يأمر بالخير، وأثبتت التقاليد السنية أنه لا يقع شيء إلا بإرادته ومع ذلك لا يحب الشر ولا يأمر به، ويفرق الأشاعرة والماتريدية بين الإرادة والرضا والمحبة، ويقسم ابن تيمية وابن القيم الإرادة إلى كونية (ما يقع) وشرعية (ما يحبه الله ويأمر به) ليفسرا وقوع المعصية بإرادته مع مخالفتها أمره."] },

  { id: "xaq-012", s: "aqidah", g: 4, d: 6, t: ["names-and-attributes", "asma-husna", "ninety-nine"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-shurūṭ and al-tawḥīd (ninety-nine names); al-Tirmidhī, Jāmiʿ (list of names); Ibn Ḥajar, Fatḥ al-Bārī; Ibn Taymiyya, Majmūʿ al-Fatāwā",
    en: ["What do scholars say about the hadith of the ninety-nine names and the list in al-Tirmidhī?", ["The statement that God has ninety-nine names is in the Ṣaḥīḥayn, while the detailed list in al-Tirmidhī is judged a later insertion by several scholars such as Ibn Ḥajar and Ibn Taymiyya, and God’s names are not limited to ninety-nine", "The hadith is fabricated and does not exist", "The list is part of the Quran", "The Ṣaḥīḥayn contain the full list"], "The Ṣaḥīḥayn report that God has ninety-nine names, and whoever enumerates (aḥṣāhā) them enters Paradise. The long list with names comes in al-Tirmidhī and Ibn Mājah through al-Walīd ibn Muslim, with differences between the lists. Scholars like Ibn Ḥajar and Ibn Taymiyya considered the enumeration an insertion by a narrator or later hand, and argued that the names are not limited to that count."],
    de: ["Was sagen Gelehrte über den Hadith von den neunundneunzig Namen und die Liste bei at-Tirmiḏī?", ["Die Aussage, Gott habe neunundneunzig Namen, steht in den Ṣaḥīḥain, während die ausführliche Liste bei at-Tirmiḏī von mehreren Gelehrten wie Ibn Ḥaǧar und Ibn Taimiyya als spätere Einfügung beurteilt wird, und Gottes Namen sind nicht auf neunundneunzig beschränkt", "Der Hadith ist erfunden und existiert nicht", "Die Liste ist Teil des Korans", "Die Ṣaḥīḥain enthalten die vollständige Liste"], "Die Ṣaḥīḥain berichten, Gott habe neunundneunzig Namen, und wer sie aufzählt (aḥṣāhā), gehe ins Paradies ein. Die lange Liste mit Namen steht bei at-Tirmiḏī und Ibn Māǧa über al-Walīd ibn Muslim, mit Unterschieden zwischen den Listen. Gelehrte wie Ibn Ḥaǧar und Ibn Taimiyya hielten die Aufzählung für eine Einfügung eines Überlieferers oder einer späteren Hand und argumentierten, die Namen seien nicht auf diese Zahl beschränkt."],
    ar: ["ماذا يقول العلماء عن حديث الأسماء التسعة والتسعين وعن قائمة الترمذي؟", ["العبارة بأن لله تسعة وتسعين اسمًا في الصحيحين، أما القائمة المفصلة في الترمذي فحكم عدد من العلماء كابن حجر وابن تيمية بأنها مدرجة، وأسماء الله لا تنحصر في تسعة وتسعين", "الحديث موضوع لا وجود له", "القائمة جزء من القرآن", "الصحيحان فيهما القائمة كاملة"], "في الصحيحين أن لله تسعة وتسعين اسمًا من أحصاها دخل الجنة، وجاء سرد الأسماء عند الترمذي وابن ماجه من طريق الوليد بن مسلم مع اختلاف بين القوائم، ورأى ابن حجر وابن تيمية وغيرهما أن السرد مدرج من بعض الرواة أو من يد متأخرة، وأن الأسماء لا تنحصر في هذا العدد."] },

  { id: "xaq-013", s: "aqidah", g: 4, d: 7, t: ["names-and-attributes", "tawqifi", "naming"], tr: ["comparative", "ashari", "athari", "maturidi"], src: "al-Bayhaqī, al-Asmāʾ wa-l-Ṣifāt; al-Ghazālī, al-Maqṣad al-Asná; al-Rāzī, Lawāmiʿ al-Bayyināt; Ibn Qudāma, Lumʿat al-Iʿtiqād",
    en: ["Are the names of God fixed by revelation (tawqīfiyya), according to the traditions?", ["The Atharīs and most Ashʿarīs held that God’s names are known only from the Quran and Sunna; some Māturīdīs and al-Bāqillānī allowed names that are correct in meaning even without a text", "All traditions allow inventing names freely", "All traditions allow only the names in the Torah", "All traditions say the names are meaningless"], "The prevailing view, held by the Atharīs, al-Bayhaqī and most Ashʿarīs, is that God’s names are tawqīfiyya: they are taken only from texts and not by analogy. Others, including al-Bāqillānī in one report and some Muʿtazila, allowed a name if its meaning is sound and not forbidden. The question affects whether one may call God by names not found in revelation, such as ‘the cause’ or ‘the necessary being’."],
    de: ["Sind die Namen Gottes nach den Traditionen durch Offenbarung festgelegt (tauqīfiyya)?", ["Die Atharīten und die meisten Ašʿariten hielten, Gottes Namen seien nur aus Koran und Sunna bekannt; manche Māturīditen und al-Bāqillānī erlaubten Namen mit richtiger Bedeutung auch ohne Text", "Alle Traditionen erlauben das freie Erfinden von Namen", "Alle Traditionen erlauben nur die Namen in der Tora", "Alle Traditionen sagen, die Namen seien bedeutungslos"], "Die vorherrschende Ansicht, vertreten von den Atharīten, al-Baihaqī und den meisten Ašʿariten, ist, dass Gottes Namen tauqīfiyya sind: Sie werden nur aus Texten und nicht durch Analogie genommen. Andere, darunter al-Bāqillānī nach einem Bericht und manche Muʿtaziliten, erlaubten einen Namen, wenn seine Bedeutung richtig und nicht verboten ist. Die Frage betrifft, ob man Gott mit nicht in der Offenbarung stehenden Namen wie ‚die Ursache‘ oder ‚das notwendige Sein‘ nennen darf."],
    ar: ["هل أسماء الله توقيفية بحسب التقاليد العقدية؟", ["رأى أهل الأثر وأكثر الأشاعرة أنها لا تؤخذ إلا من الكتاب والسنة، وأجاز الباقلاني في رواية وبعض الماتريدية ما صح معناه ولو بلا نص", "تجيز كل التقاليد اختراع الأسماء بحرية", "تجيز كل التقاليد أسماء التوراة فقط", "تقول كل التقاليد إن الأسماء بلا معنى"], "الرأي الغالب عند أهل الأثر والبيهقي وأكثر الأشاعرة أن أسماء الله توقيفية فلا تؤخذ إلا من النصوص ولا تثبت بالقياس، وأجاز آخرون ومنهم الباقلاني في رواية وبعض المعتزلة إطلاق اسم صحيح المعنى غير ممنوع، وتتعلق المسألة بجواز تسمية الله بما لم يرد في الوحي كـ«العلة» و«واجب الوجود»."] },

  { id: "xaq-014", s: "aqidah", g: 4, d: 7, t: ["vision", "ruya", "ahl-al-sunna"], tr: ["sunni", "comparative"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-tawḥīd and Kitāb mawāqīt al-ṣalāh (ḥadīth Jarīr); al-Ṭaḥāwī, al-ʿAqīda; al-Ashʿarī, al-Ibāna",
    en: ["What is the Sunni position on seeing God in the hereafter, and who denied it?", ["Ahl al-Sunna affirm that the believers will see their Lord in the hereafter, based on the Quran and the ḥadīth of Jarīr (seeing the full moon); the Muʿtazila and Jahmiyya denied it and interpreted the texts figuratively", "All groups affirmed that God can be seen in this world", "No group discussed the matter", "All groups denied it"], "The Sunni creeds affirm the vision (ruʾya) of God by believers in the hereafter without limit or likeness. The ḥadīth of Jarīr ibn ʿAbd Allāh in al-Bukhārī compares the vision to seeing the full moon. The Muʿtazila denied it on rational grounds and interpreted the verses as meaning waiting for God’s reward. Ahl al-Sunna also differ on whether the Prophet ﷺ saw his Lord with his eyes on the Night of the Ascent, with ʿĀʾisha denying it and Ibn ʿAbbās affirming a vision by the heart or eye."],
    de: ["Was ist die sunnitische Position zum Schauen Gottes im Jenseits, und wer bestritt es?", ["Ahl as-Sunna bejahen, dass die Gläubigen im Jenseits ihren Herrn sehen werden, gestützt auf den Koran und den Hadith von Ǧarīr (das Sehen des Vollmonds); die Muʿtazila und Ǧahmiyya bestritten es und deuteten die Texte figürlich", "Alle Gruppen bejahten, dass Gott in dieser Welt gesehen werden kann", "Keine Gruppe erörterte die Frage", "Alle Gruppen bestritten es"], "Die sunnitischen Bekenntnisse bejahen das Schauen (ruʾya) Gottes durch die Gläubigen im Jenseits ohne Grenze oder Vergleich. Der Hadith von Ǧarīr ibn ʿAbd Allāh bei al-Buḫārī vergleicht das Schauen mit dem Sehen des Vollmonds. Die Muʿtazila bestritten es aus rationalen Gründen und deuteten die Verse als Erwarten von Gottes Lohn. Ahl as-Sunna sind auch uneins, ob der Prophet ﷺ in der Nacht des Aufstiegs seinen Herrn mit den Augen sah, wobei ʿĀʾiša es verneinte und Ibn ʿAbbās ein Sehen mit dem Herzen oder Auge bejahte."],
    ar: ["ما موقف أهل السنة من رؤية الله في الآخرة ومن أنكرها؟", ["أثبت أهل السنة رؤية المؤمنين ربهم في الآخرة بالقرآن وحديث جرير في رؤية القمر ليلة البدر، وأنكرها المعتزلة والجهمية وتأولوا النصوص", "أثبتت كل الفرق إمكان رؤية الله في الدنيا", "لم تبحث فرقة المسألة", "أنكرتها كل الفرق"], "تثبت العقائد السنية رؤية المؤمنين لله في الآخرة بلا حد ولا تشبيه، ويشبه حديث جرير بن عبد الله في البخاري الرؤية برؤية القمر ليلة البدر، وأنكرها المعتزلة عقلًا وفسروا الآيات بانتظار ثواب الله، ويختلف أهل السنة في رؤية النبي ﷺ ربه ليلة المعراج بعينه، فنفتها عائشة وأثبت ابن عباس رؤية بالقلب أو بالعين."] },

  { id: "xaq-015", s: "aqidah", g: 4, d: 6, t: ["prophecy", "karamat", "mujizat"], src: "al-Ṭaḥāwī, al-ʿAqīda; al-Bāqillānī, al-Bayān; al-Subkī, Ṭabaqāt; Ibn Taymiyya, al-Nubuwwāt",
    en: ["What distinguishes a miracle of a prophet (muʿjiza) from the wonder given to a righteous person (karāma) in the classical creeds?", ["The muʿjiza is joined to a claim of prophecy with a challenge and cannot be matched; the karāma is a wonder shown at the hands of a righteous follower, without a claim of prophecy, and is affirmed by Ahl al-Sunna against the Muʿtazila", "The karāma is greater than the muʿjiza", "Both are only done by Satan", "There is no difference and neither is affirmed"], "Ahl al-Sunna affirm karāmāt for the saints (awliyāʾ) such as the story of Maryam’s food or the Companions’ reported wonders. The Muʿtazila mostly denied them, fearing confusion with prophecy. The muʿjiza is distinguished by claim of prophecy, challenge (taḥaddī) and inability of others to match it. The Ashʿarī al-Bāqillānī and others set out the conditions."],
    de: ["Was unterscheidet in den klassischen Bekenntnissen das Wunder eines Propheten (muʿǧiza) vom Wunder, das einem Rechtschaffenen gegeben wird (karāma)?", ["Die Muʿǧiza ist mit einem Anspruch auf Prophetie und einer Herausforderung verbunden und nicht nachzuahmen; die Karāma ist ein Wunder durch einen rechtschaffenen Anhänger ohne Prophetieanspruch und wird von Ahl as-Sunna gegen die Muʿtazila bejaht", "Die Karāma ist größer als die Muʿǧiza", "Beide werden nur vom Satan bewirkt", "Es gibt keinen Unterschied, und keines wird bejaht"], "Ahl as-Sunna bejahen Karāmāt für die Gottesfreunde (awliyāʾ), etwa die Geschichte von Maryams Speise oder berichtete Wunder der Gefährten. Die Muʿtazila bestritten sie meist aus Furcht vor Verwechslung mit Prophetie. Die Muʿǧiza zeichnet sich durch Prophetieanspruch, Herausforderung (taḥaddī) und Unfähigkeit anderer, es nachzuahmen, aus. Der Ašʿarit al-Bāqillānī und andere legten die Bedingungen dar."],
    ar: ["ما الذي يميز معجزة النبي من كرامة الولي في العقائد الكلاسيكية؟", ["المعجزة مقرونة بدعوى النبوة والتحدي ولا يمكن معارضتها، والكرامة أمر خارق على يد تابع صالح بلا دعوى نبوة وأثبتها أهل السنة خلافًا للمعتزلة", "الكرامة أعظم من المعجزة", "كلتاهما من الشيطان", "لا فرق ولا تثبت إحداهما"], "يثبت أهل السنة كرامات الأولياء كقصة رزق مريم وما نُقل عن الصحابة، وأنكرها أكثر المعتزلة خشية اشتباهها بالنبوة، وتتميز المعجزة بدعوى النبوة والتحدي وعجز الخلق عن المعارضة، وقد بيّن الباقلاني الأشعري وغيره شروطها."] },

  { id: "xaq-016", s: "aqidah", g: 4, d: 7, t: ["prophecy", "isma", "infallibility"], tr: ["comparative", "sunni"], src: "al-Qāḍī ʿIyāḍ, al-Shifā, Part 2; Ibn Ḥajar, Fatḥ al-Bārī; al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya; al-Rāzī, ʿIṣmat al-Anbiyāʾ",
    en: ["What do Sunni scholars hold about the infallibility (ʿiṣma) of prophets?", ["Prophets are protected from major sins and from error in conveying the message; whether minor slips occurred before or after prophecy is debated, with al-Rāzī and al-Qāḍī ʿIyāḍ giving detailed positions", "Prophets sin like any other person without any protection", "Only the final Prophet ﷺ has any protection", "Prophets are divine"], "Sunni scholars agree on protection in conveying the message and from disbelief. For sins, most hold that prophets are protected from major sins and from those that show baseness, while some permit minor slips that God corrects, as in some verses about Adam and Yūnus. Al-Qāḍī ʿIyāḍ in al-Shifā and al-Rāzī in ʿIṣmat al-Anbiyāʾ give extended discussions and read such verses as leaving the better course (khilāf al-awlā)."],
    de: ["Was halten sunnitische Gelehrte zur Unfehlbarkeit (ʿiṣma) der Propheten?", ["Propheten sind vor großen Sünden und vor Irrtum bei der Übermittlung der Botschaft geschützt; ob kleine Verfehlungen vor oder nach der Prophetie vorkamen, ist umstritten, wobei ar-Rāzī und al-Qāḍī ʿIyāḍ ausführliche Positionen geben", "Propheten sündigen wie jeder andere ohne Schutz", "Nur der letzte Prophet ﷺ hat irgendeinen Schutz", "Propheten sind göttlich"], "Sunnitische Gelehrte sind sich über den Schutz bei der Übermittlung der Botschaft und vor Unglauben einig. Bei Sünden halten die meisten, dass Propheten vor großen Sünden und vor solchen, die Niedrigkeit zeigen, geschützt sind, während manche kleine Verfehlungen erlauben, die Gott korrigiert, wie in einigen Versen über Adam und Yūnus. Al-Qāḍī ʿIyāḍ in aš-Šifā und ar-Rāzī in ʿIṣmat al-Anbiyāʾ geben ausführliche Erörterungen und lesen solche Verse als Verlassen des Besseren (ḫilāf al-aulā)."],
    ar: ["ماذا يرى علماء السنة في عصمة الأنبياء؟", ["الأنبياء معصومون من الكبائر ومن الخطأ في تبليغ الرسالة، والخلاف في الصغائر قبل البعثة وبعدها، وفصل الرازي والقاضي عياض مواقفهم", "يذنب الأنبياء كسائر الناس بلا حماية", "العصمة لخاتم الأنبياء ﷺ وحده", "الأنبياء آلهة"], "يتفق علماء السنة على عصمتهم في التبليغ ومن الكفر، وفي الذنوب يرى الأكثر عصمتهم من الكبائر ومن كل ما يدل على الخسة، وجوّز بعضهم صغائر يصححها الله كما في بعض الآيات عن آدم ويونس، ويفصل القاضي عياض في «الشفا» والرازي في «عصمة الأنبياء» ويحملان هذه الآيات على ترك الأولى."] },

  { id: "xaq-017", s: "aqidah", g: 4, d: 6, t: ["companions", "caliphs-ranking", "afdaliyya"], tr: ["sunni", "comparative"], src: "al-Ṭaḥāwī, al-ʿAqīda; Ibn Abī al-ʿIzz, Sharḥ al-Ṭaḥāwiyya; al-Bukhārī, Ṣaḥīḥ (Ibn ʿUmar: ranking in the Prophet’s time); Ibn Taymiyya, Minhāj al-Sunna",
    en: ["How do Sunni creeds rank the four Rightly Guided Caliphs, and what disagreement existed between ʿUthmān and ʿAlī?", ["In order Abū Bakr, ʿUmar, ʿUthmān and ʿAlī in caliphate; early scholars in Kūfa debated whether ʿAlī was better than ʿUthmān, and Ahl al-Sunna settled on ʿUthmān before ʿAlī", "ʿAlī before Abū Bakr by consensus", "ʿUmar before Abū Bakr by consensus", "All four are exactly equal in rank"], "Al-Ṭaḥāwī and the Sunni creeds affirm the order in excellence matching the order of caliphate. In early times some of the people of Kūfa preferred ʿAlī to ʿUthmān, and the Sunni consensus later settled on ʿUthmān first, as Ibn Taymiyya states. Abū Ḥanīfa is reported to have first held ʿAlī better and later returned to the majority. The Shīʿa hold ʿAlī was the rightful successor."],
    de: ["Wie ordnen sunnitische Bekenntnisse die vier rechtgeleiteten Kalifen, und welche Meinungsverschiedenheit bestand zwischen ʿUṯmān und ʿAlī?", ["In der Reihenfolge Abū Bakr, ʿUmar, ʿUṯmān und ʿAlī im Kalifat; frühe Gelehrte in Kufa debattierten, ob ʿAlī besser sei als ʿUṯmān, und Ahl as-Sunna einigten sich auf ʿUṯmān vor ʿAlī", "ʿAlī vor Abū Bakr nach Konsens", "ʿUmar vor Abū Bakr nach Konsens", "Alle vier sind im Rang genau gleich"], "Aṭ-Ṭaḥāwī und die sunnitischen Bekenntnisse bejahen die Reihenfolge im Vorzug entsprechend der Reihenfolge des Kalifats. In früher Zeit zogen einige Leute von Kufa ʿAlī ʿUṯmān vor, und der sunnitische Konsens einigte sich später auf ʿUṯmān zuerst, wie Ibn Taimiyya feststellt. Von Abū Ḥanīfa wird berichtet, er habe zuerst ʿAlī für besser gehalten und sei später zur Mehrheit zurückgekehrt. Die Schia hält ʿAlī für den rechtmäßigen Nachfolger."],
    ar: ["كيف تُرتّب العقائد السنية الخلفاء الراشدين الأربعة وما الخلاف الذي كان بين عثمان وعلي؟", ["أبو بكر فعمر فعثمان فعلي في الخلافة، وتناظر بعض الكوفيين الأوائل في تفضيل علي على عثمان فاستقر أهل السنة على تقديم عثمان", "علي قبل أبي بكر بالإجماع", "عمر قبل أبي بكر بالإجماع", "الأربعة متساوون تمامًا في الرتبة"], "تقرر العقائد السنية كعقيدة الطحاوي أن ترتيبهم في الفضل كترتيبهم في الخلافة، وقد فضّل بعض أهل الكوفة قديمًا عليًّا على عثمان ثم استقر إجماع أهل السنة على تقديم عثمان كما ذكر ابن تيمية، ويُروى عن أبي حنيفة أنه قال بتفضيل علي أولًا ثم رجع إلى قول الجمهور، وتقول الشيعة إن عليًّا هو الخليفة الشرعي."] },

  { id: "xaq-018", s: "aqidah", g: 4, d: 7, t: ["companions", "fitna", "jamal-siffin"], tr: ["sunni", "comparative"], src: "Ibn Ḥajar, Fatḥ al-Bārī; Ibn Taymiyya, Minhāj al-Sunna; al-Dhahabī, Siyar; al-Ṭaḥāwī, al-ʿAqīda; Ibn al-ʿArabī, al-ʿAwāṣim min al-Qawāṣim",
    en: ["What is the Sunni principle about the conflicts between the Companions (Jamal and Ṣiffīn)?", ["To refrain from speaking ill of the Companions, to consider them mujtahids who may have erred or been right, and to hold that ʿAlī was closer to the truth in these conflicts, as most Sunni scholars state", "To curse the Companions who fought", "To say all participants were unbelievers", "To avoid mentioning that these battles occurred"], "Al-Ṭaḥāwī and other creeds say we love the Companions and mention only good of them. For the conflicts, most scholars hold that ʿAlī was right in the Battle of the Camel and Ṣiffīn, while Ṭalḥa, al-Zubayr, ʿĀʾisha and Muʿāwiya acted from ijtihād, and are excused and may be rewarded once. Some early Basran scholars were more reserved, and Ibn al-ʿArabī in al-ʿAwāṣim defended the Companions strongly."],
    de: ["Was ist der sunnitische Grundsatz zu den Konflikten zwischen den Gefährten (Kamel- und Ṣiffīn-Schlacht)?", ["Sich des Schlechtredens über die Gefährten zu enthalten, sie als Mudschtahids zu betrachten, die geirrt haben oder recht gehabt haben können, und zu halten, dass ʿAlī in diesen Konflikten der Wahrheit näher war, wie die meisten sunnitischen Gelehrten feststellen", "Die kämpfenden Gefährten zu verfluchen", "Alle Beteiligten für ungläubig zu erklären", "Zu vermeiden zu erwähnen, dass diese Schlachten stattfanden"], "Aṭ-Ṭaḥāwī und andere Bekenntnisse sagen, wir lieben die Gefährten und erwähnen nur Gutes von ihnen. Zu den Konflikten halten die meisten Gelehrten, dass ʿAlī in der Kamelschlacht und bei Ṣiffīn im Recht war, während Ṭalḥa, az-Zubair, ʿĀʾiša und Muʿāwiya aus Iǧtihād handelten, entschuldigt sind und einmal belohnt werden können. Einige frühe basrische Gelehrte waren zurückhaltender, und Ibn al-ʿArabī verteidigte die Gefährten in al-ʿAwāṣim stark."],
    ar: ["ما المبدأ السني في الخلافات بين الصحابة (الجمل وصفين)؟", ["الإمساك عن سب الصحابة واعتبارهم مجتهدين قد يخطئون ويصيبون، ويرى أكثر علماء السنة أن عليًّا كان أقرب إلى الحق في هذه الخلافات", "لعن الصحابة الذين تقاتلوا", "القول بأن المشاركين كلهم كفار", "تجنب ذكر وقوع هذه المعارك"], "قال الطحاوي وغيره إنهم يحبون الصحابة ولا يذكرونهم إلا بخير، وفي النزاع يرى أكثر العلماء أن عليًّا كان على حق في الجمل وصفين وأن طلحة والزبير وعائشة ومعاوية اجتهدوا فهم معذورون وقد يؤجرون أجرًا واحدًا، وتوقف بعض أوائل البصريين أكثر، ودافع ابن العربي في «العواصم من القواصم» عن الصحابة دفاعًا قويًّا."] },

  { id: "xaq-019", s: "aqidah", g: 4, d: 6, t: ["eschatology", "barzakh", "grave-punishment"], tr: ["sunni", "comparative"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-janāʾiz (ʿadhāb al-qabr); Muslim, Ṣaḥīḥ; al-Ṭaḥāwī, al-ʿAqīda; Ibn Abī al-ʿIzz, Sharḥ al-Ṭaḥāwiyya",
    en: ["What is the Sunni position on the punishment and bliss of the grave, and who denied it?", ["Ahl al-Sunna affirm it on the basis of Quran and numerous reports, while some Muʿtazila and others denied it or reinterpreted it", "All schools denied the grave’s punishment", "No report mentions it", "It is held to apply to the body only, never to the soul"], "The reports in the Ṣaḥīḥayn on the questioning in the grave and the punishment or bliss of the grave are numerous, and the Sunni creeds affirm them. Some Muʿtazila (like Ḍirār ibn ʿAmr) and the Khawārij denied it, as it was thought to be against reason. Ahl al-Sunna do not specify the manner beyond the texts, with differing views on whether it is on the soul alone or on both soul and body."],
    de: ["Was ist die sunnitische Position zu Strafe und Wonne im Grab, und wer bestritt sie?", ["Ahl as-Sunna bejahen sie aufgrund von Koran und zahlreichen Berichten, während einige Muʿtaziliten und andere sie bestritten oder umdeuteten", "Alle Schulen bestritten die Strafe im Grab", "Kein Bericht erwähnt sie", "Sie gilt nur für den Körper, nie für die Seele"], "Die Berichte in den Ṣaḥīḥain über die Befragung im Grab und Strafe oder Wonne des Grabes sind zahlreich, und die sunnitischen Bekenntnisse bejahen sie. Einige Muʿtaziliten (wie Ḍirār ibn ʿAmr) und die Ḫawāriǧ bestritten sie, da sie als verstandeswidrig galt. Ahl as-Sunna legen die Art nicht über die Texte hinaus fest, mit unterschiedlichen Ansichten, ob sie nur die Seele oder Seele und Körper betrifft."],
    ar: ["ما موقف أهل السنة من عذاب القبر ونعيمه ومن أنكره؟", ["أثبته أهل السنة بالقرآن وأخبار كثيرة وأنكره بعض المعتزلة وغيرهم أو أولوه", "أنكرت المذاهب كلها عذاب القبر", "لا خبر يذكره", "يقع على الجسد فقط لا على الروح"], "أخبار سؤال القبر وعذابه ونعيمه في الصحيحين كثيرة وأثبتتها العقائد السنية، وأنكرها بعض المعتزلة كضرار بن عمرو والخوارج لظنهم أنه مخالف للعقل، ولا يحدد أهل السنة كيفيته فوق النصوص ويختلفون في وقوعه على الروح وحدها أو على الروح والجسد."] },

  { id: "xaq-020", s: "aqidah", g: 4, d: 7, t: ["eschatology", "mizan-sirat-hawd", "intercession"], tr: ["sunni", "comparative"], src: "al-Ṭaḥāwī, al-ʿAqīda; al-Bukhārī, Ṣaḥīḥ, Kitāb al-riqāq and Kitāb al-tawḥīd; Muslim, Ṣaḥīḥ, Kitāb al-īmān; al-Nasafī, al-ʿAqāʾid",
    en: ["Which items of the afterlife do the Sunni creeds affirm, and what did the Muʿtazila say regarding intercession?", ["The Scale, the Bridge (al-ṣirāṭ), the Pond (al-ḥawḍ) and intercession for people of major sin; the Muʿtazila denied intercession for those who committed major sins and died without repentance", "Only the Scale; all others are rejected", "Only the Pond; the Bridge is rejected by all", "The creeds do not mention any of them"], "The Sunni creeds (such as al-Ṭaḥāwī’s) affirm the questioning, the Scale (al-mīzān), the Bridge (al-ṣirāṭ), the Pond (al-ḥawḍ) and the intercession (shafāʿa) of the Prophet ﷺ for those of his community who committed major sins, based on mutawātir-level reports. The Muʿtazila limited intercession to raising the rank of the righteous, since in their view the unrepentant major sinner is eternally in the Fire. Sunnis hold that such a person is under God’s will."],
    de: ["Welche Dinge des Jenseits bejahen die sunnitischen Bekenntnisse, und was sagten die Muʿtazila zur Fürsprache?", ["Die Waage, die Brücke (aṣ-Ṣirāṭ), das Becken (al-Ḥauḍ) und die Fürsprache für Menschen mit großer Sünde; die Muʿtazila bestritten die Fürsprache für jene, die große Sünden begingen und ohne Reue starben", "Nur die Waage; alles andere wird abgelehnt", "Nur das Becken; die Brücke wird von allen abgelehnt", "Die Bekenntnisse erwähnen keines davon"], "Die sunnitischen Bekenntnisse (wie das von aṭ-Ṭaḥāwī) bejahen die Befragung, die Waage (al-mīzān), die Brücke (aṣ-ṣirāṭ), das Becken (al-ḥauḍ) und die Fürsprache (šafāʿa) des Propheten ﷺ für die aus seiner Gemeinschaft, die große Sünden begingen, gestützt auf Berichte von Mutawātir-Rang. Die Muʿtazila beschränkten die Fürsprache auf die Rangerhöhung der Rechtschaffenen, da der nicht bereuende große Sünder nach ihrer Sicht ewig im Feuer ist. Die Sunniten halten, dass eine solche Person unter Gottes Willen steht."],
    ar: ["ما الأمور الأخروية التي تثبتها العقائد السنية وماذا قال المعتزلة في الشفاعة؟", ["الميزان والصراط والحوض والشفاعة لأهل الكبائر، وأنكر المعتزلة الشفاعة لمن ارتكب الكبائر ومات بلا توبة", "الميزان فقط وسائرها مردود", "الحوض فقط والصراط مردود عند الجميع", "العقائد لا تذكر شيئًا منها"], "تثبت العقائد السنية كالطحاوية السؤال والميزان والصراط والحوض وشفاعة النبي ﷺ لأهل الكبائر من أمته بأخبار بلغت درجة التواتر، وحصر المعتزلة الشفاعة في رفع درجات الصالحين لأن مرتكب الكبيرة بلا توبة مخلد في النار عندهم، ويرى أهل السنة أنه تحت مشيئة الله."] },

  { id: "xaq-021", s: "aqidah", g: 4, d: 6, t: ["muslim-sects", "khawarij", "murjia", "mutazila"], src: "al-Ashʿarī, Maqālāt al-Islāmiyyīn; al-Shahrastānī, al-Milal wa-l-Niḥal; al-Baghdādī, al-Farq bayna al-Firaq",
    en: ["Which statement correctly summarises the early disputes about the status of the grave sinner (murtakib al-kabīra)?", ["The Khawārij called him an unbeliever, the Murjiʾa postponed judgment and stressed faith, the Muʿtazila placed him in an intermediate position, and Ahl al-Sunna held him a believer with sin under God’s will", "All groups said he is a perfect believer", "All groups said he is an unbeliever", "No group discussed him"], "The dispute began after the first civil strife. The Khawārij held that a major sinner leaves the community of believers. The Murjiʾa postponed his final judgment to God and gave faith priority. Wāṣil ibn ʿAṭāʾ and the Muʿtazila held he is neither believer nor unbeliever but in an intermediate state, and will remain in the Fire if he dies unrepentant. Ahl al-Sunna say he remains a believer with deficient faith, under God’s will."],
    de: ["Welche Aussage fasst die frühen Streitigkeiten über den Status des großen Sünders (murtakib al-kabīra) richtig zusammen?", ["Die Ḫawāriǧ nannten ihn ungläubig, die Murǧiʾa vertagten das Urteil und betonten den Glauben, die Muʿtazila stellten ihn in eine Zwischenstellung, und Ahl as-Sunna hielten ihn für einen Gläubigen mit Sünde unter Gottes Willen", "Alle Gruppen sagten, er sei ein vollkommener Gläubiger", "Alle Gruppen sagten, er sei ungläubig", "Keine Gruppe erörterte ihn"], "Der Streit begann nach der ersten Bürgerkriegsfitna. Die Ḫawāriǧ hielten, ein großer Sünder verlasse die Gemeinschaft der Gläubigen. Die Murǧiʾa vertagten sein endgültiges Urteil auf Gott und gaben dem Glauben Vorrang. Wāṣil ibn ʿAṭāʾ und die Muʿtazila hielten ihn weder für gläubig noch ungläubig, sondern in einem Zwischenzustand, und im Feuer bleibend, wenn er unbereut stirbt. Ahl as-Sunna sagen, er bleibe ein Gläubiger mit mangelhaftem Glauben unter Gottes Willen."],
    ar: ["أي عبارة تلخص على الوجه الصحيح الخلافات المبكرة في حكم مرتكب الكبيرة؟", ["كفّره الخوارج وأرجأ المرجئة الحكم وقدموا الإيمان وجعله المعتزلة في منزلة بين المنزلتين وعدّه أهل السنة مؤمنًا عاصيًا تحت المشيئة", "قالت كل الفرق إنه مؤمن كامل", "قالت كل الفرق إنه كافر", "لم تبحثه فرقة"], "بدأ الخلاف بعد الفتنة الأولى، فرأى الخوارج أن مرتكب الكبيرة يخرج من جماعة المؤمنين، وأرجأ المرجئة حكمه إلى الله وقدموا الإيمان، وقال واصل بن عطاء والمعتزلة إنه لا مؤمن ولا كافر بل في منزلة بين المنزلتين ومخلد في النار إن مات بلا توبة، وقال أهل السنة إنه مؤمن ناقص الإيمان تحت مشيئة الله."] },

  { id: "xaq-022", s: "aqidah", g: 4, d: 7, t: ["mutazila", "five-principles"], tr: ["comparative"], src: "al-Qāḍī ʿAbd al-Jabbār, Sharḥ al-Uṣūl al-Khamsa; al-Ashʿarī, Maqālāt al-Islāmiyyīn; al-Shahrastānī, al-Milal wa-l-Niḥal",
    en: ["Which are the five principles (al-uṣūl al-khamsa) of the Muʿtazila?", ["Divine unity (tawḥīd), justice (ʿadl), the promise and threat (al-waʿd wa-l-waʿīd), the intermediate position (al-manzila bayna al-manzilatayn) and commanding right and forbidding wrong", "Prayer, fasting, zakāt, ḥajj and testimony", "Sharia, tarīqa, ḥaqīqa, maʿrifa and tawba", "The Quran, the Sunna, consensus, analogy and custom"], "The Muʿtazila, as set out by al-Qāḍī ʿAbd al-Jabbār, built their doctrine on five principles. Tawḥīd for them includes denial of eternal attributes distinct from the essence; ʿadl includes the claim that God does not create evil acts; the waʿd wa-l-waʿīd says reward and punishment must be carried out; the intermediate position concerns the grave sinner. These led to disputes with the Ashʿarīs and Atharīs."],
    de: ["Welche sind die fünf Prinzipien (al-uṣūl al-ḫamsa) der Muʿtazila?", ["Die Einheit Gottes (tauḥīd), die Gerechtigkeit (ʿadl), Verheißung und Drohung (al-waʿd wa-l-waʿīd), die Zwischenstellung (al-manzila baina l-manzilatain) und das Gebieten des Rechten und Verbieten des Verwerflichen", "Gebet, Fasten, Zakāt, Ḥaǧǧ und Bekenntnis", "Scharia, Ṭarīqa, Ḥaqīqa, Maʿrifa und Tauba", "Der Koran, die Sunna, der Konsens, die Analogie und der Brauch"], "Die Muʿtazila, wie al-Qāḍī ʿAbd al-Ǧabbār sie darlegt, bauten ihre Lehre auf fünf Prinzipien. Der Tauḥīd umfasst für sie die Leugnung ewiger Attribute, die vom Wesen verschieden sind; die ʿAdl umfasst die Behauptung, Gott schaffe keine bösen Handlungen; al-waʿd wa-l-waʿīd besagt, Belohnung und Strafe müssten vollzogen werden; die Zwischenstellung betrifft den großen Sünder. Daraus folgten Streitigkeiten mit den Ašʿariten und Atharīten."],
    ar: ["ما الأصول الخمسة للمعتزلة؟", ["التوحيد والعدل والوعد والوعيد والمنزلة بين المنزلتين والأمر بالمعروف والنهي عن المنكر", "الصلاة والصيام والزكاة والحج والشهادة", "الشريعة والطريقة والحقيقة والمعرفة والتوبة", "القرآن والسنة والإجماع والقياس والعرف"], "بنى المعتزلة كما عرض القاضي عبد الجبار مذهبهم على خمسة أصول: التوحيد وعندهم يتضمن نفي الصفات القديمة الزائدة على الذات، والعدل ويتضمن أن الله لا يخلق أفعال الشر، والوعد والوعيد بإنفاذ الثواب والعقاب، والمنزلة بين المنزلتين في مرتكب الكبيرة، وهذه أدت إلى خلافات مع الأشاعرة وأهل الأثر."] },

  { id: "xaq-023", s: "aqidah", g: 4, d: 7, t: ["jahmiyya", "ahmad-ibn-hanbal", "mihna"], tr: ["athari", "sunni"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, Aḥmad ibn Ḥanbal; Ibn Kathīr, al-Bidāya wa-l-Nihāya; Aḥmad ibn Ḥanbal, al-Radd ʿalā al-Zanādiqa wa-l-Jahmiyya; al-Ṭabarī, Taʾrīkh",
    en: ["What was the miḥna in the caliphates of al-Maʾmūn, al-Muʿtaṣim and al-Wāthiq, and what role did Aḥmad ibn Ḥanbal play?", ["A state inquisition requiring scholars to say the Quran is created; Aḥmad ibn Ḥanbal refused and was flogged and imprisoned, and the policy was ended under al-Mutawakkil", "A war with the Byzantines", "A tax on scholars", "A ban on teaching hadith in Baghdad only"], "From about 218 AH, al-Maʾmūn imposed the doctrine of the Quran’s createdness, supported by the Muʿtazilī judge Aḥmad ibn Abī Duʾād, and tested judges and scholars. Aḥmad ibn Ḥanbal refused, was imprisoned and flogged under al-Muʿtaṣim, and became a symbol of steadfastness to Ahl al-Sunna. Al-Mutawakkil ended the inquisition around 234 AH and supported the Sunni scholars."],
    de: ["Was war die Miḥna in den Kalifaten von al-Maʾmūn, al-Muʿtaṣim und al-Wāṯiq, und welche Rolle spielte Aḥmad ibn Ḥanbal?", ["Eine staatliche Inquisition, die Gelehrte zwang zu sagen, der Koran sei erschaffen; Aḥmad ibn Ḥanbal weigerte sich, wurde ausgepeitscht und eingekerkert, und die Politik wurde unter al-Mutawakkil beendet", "Ein Krieg mit den Byzantinern", "Eine Steuer auf Gelehrte", "Ein Verbot, Hadith nur in Bagdad zu lehren"], "Ab etwa 218 n. H. erzwang al-Maʾmūn die Lehre von der Erschaffenheit des Korans, unterstützt vom muʿtazilitischen Richter Aḥmad ibn Abī Duʾād, und prüfte Richter und Gelehrte. Aḥmad ibn Ḥanbal weigerte sich, wurde unter al-Muʿtaṣim eingekerkert und ausgepeitscht und wurde für Ahl as-Sunna ein Symbol der Standhaftigkeit. Al-Mutawakkil beendete die Inquisition um 234 n. H. und unterstützte die sunnitischen Gelehrten."],
    ar: ["ما المحنة في خلافة المأمون والمعتصم والواثق وما دور أحمد بن حنبل فيها؟", ["محاكمة رسمية تُلزم العلماء بالقول بخلق القرآن، وامتنع أحمد بن حنبل فجُلد وسُجن، وأنهاها المتوكل", "حرب مع الروم", "ضريبة على العلماء", "منع تدريس الحديث في بغداد فقط"], "فرض المأمون نحو سنة 218هـ القول بخلق القرآن بدعم القاضي المعتزلي أحمد بن أبي دؤاد وامتحن القضاة والعلماء، فامتنع أحمد بن حنبل وسُجن وجُلد في عهد المعتصم وصار رمزًا للثبات عند أهل السنة، وأنهى المتوكل المحنة نحو سنة 234هـ ونصر علماء السنة."] },

  { id: "xaq-024", s: "aqidah", g: 4, d: 6, t: ["ashari", "history", "al-ibana"], tr: ["ashari", "athari"], src: "Ibn ʿAsākir, Tabyīn Kadhib al-Muftarī; al-Subkī, Ṭabaqāt al-Shāfiʿiyya al-Kubrā; al-Ashʿarī, al-Ibāna and al-Lumaʿ; Ibn Taymiyya, Majmūʿ al-Fatāwā",
    en: ["What are the stages usually attributed to al-Ashʿarī’s intellectual life, and what is debated?", ["Muʿtazilī, then a Kullābī phase, then a return to the way of Aḥmad as stated in al-Ibāna; the Ashʿarīs hold that the later view is the Ashʿarī system in al-Lumaʿ, while others see al-Ibāna as his final book", "He was born in Madīna and never changed opinions", "He was always a Shīʿī", "He was a Christian convert and wrote nothing"], "Al-Ashʿarī (d. 324 AH) studied under the Muʿtazilī al-Jubbāʾī, then left Muʿtazilism. Later authors, such as Ibn Taymiyya, describe a Kullābī stage, then a final stage in which he affirmed the creed of Aḥmad in al-Ibāna. The Ashʿarīs, including Ibn ʿAsākir and al-Subkī, hold that al-Ibāna and al-Lumaʿ agree in essence, and the dispute over which expresses his final view continues."],
    de: ["Welche Stufen werden al-Ašʿarīs geistigem Leben üblicherweise zugeschrieben, und was ist umstritten?", ["Muʿtazilit, dann eine Kullābī-Phase, dann eine Rückkehr zum Weg Aḥmads, wie in al-Ibāna festgehalten; die Ašʿariten halten, das System von al-Lumaʿ sei das spätere ašʿaritische, während andere al-Ibāna als sein letztes Buch sehen", "Er wurde in Medina geboren und änderte nie seine Meinung", "Er war immer Schiit", "Er war ein christlicher Konvertit und schrieb nichts"], "Al-Ašʿarī (gest. 324 n. H.) studierte beim Muʿtaziliten al-Ǧubbāʾī und wandte sich dann vom Muʿtazilismus ab. Spätere Autoren wie Ibn Taimiyya beschreiben eine Kullābī-Stufe, dann eine letzte Stufe, in der er das Bekenntnis Aḥmads in al-Ibāna bejahte. Die Ašʿariten, einschließlich Ibn ʿAsākir und as-Subkī, halten, al-Ibāna und al-Lumaʿ stimmten im Wesentlichen überein, und der Streit, welches seine letzte Ansicht ausdrückt, dauert an."],
    ar: ["ما المراحل التي تُنسب عادة إلى حياة الأشعري الفكرية وما المختلف فيه؟", ["اعتزال ثم مرحلة كلابية ثم رجوع إلى طريقة أحمد كما في «الإبانة»، ويرى الأشاعرة أن منهج «اللمع» هو المتأخر بينما يراها آخرون «الإبانة» آخر كتبه", "ولد في المدينة ولم يغير رأيه قط", "كان شيعيًّا دائمًا", "كان نصرانيًّا أسلم ولم يؤلف شيئًا"], "تتلمذ الأشعري (ت 324هـ) على المعتزلي الجبائي ثم رجع عن الاعتزال، ويصف متأخرون كابن تيمية مرحلة كلابية ثم مرحلة أخيرة أثبت فيها عقيدة أحمد في «الإبانة»، ويرى الأشاعرة ومنهم ابن عساكر والسبكي أن «الإبانة» و«اللمع» متفقان في الجوهر ويستمر الخلاف في أيهما يعبر عن رأيه الأخير."] },

  { id: "xaq-025", s: "aqidah", g: 4, d: 7, t: ["maturidi", "history", "samarqand"], tr: ["maturidi", "hanafi"], src: "al-Māturīdī, Kitāb al-Tawḥīd and Taʾwīlāt Ahl al-Sunna; Abū al-Muʿīn al-Nasafī, Tabṣirat al-Adilla; al-Bazdawī, Uṣūl al-Dīn; al-Nasafī, al-ʿAqāʾid",
    en: ["What are the principal Māturīdī works and what is the relation to Abū Ḥanīfa?", ["Kitāb al-Tawḥīd and Taʾwīlāt Ahl al-Sunna of al-Māturīdī, with later systematic works by al-Nasafī and al-Bazdawī; the school sees itself as the creedal expression of the Ḥanafī tradition", "al-Muwaṭṭaʾ of Mālik; the school follows Mālik", "al-Risāla of al-Shāfiʿī; the school follows al-Shāfiʿī", "Nahj al-Balāgha; the school is Shīʿī"], "Abū Manṣūr al-Māturīdī (d. 333 AH) of Samarqand wrote Kitāb al-Tawḥīd on creed and Taʾwīlāt Ahl al-Sunna on Quranic exegesis. Later Māturīdī works include al-Bazdawī’s Uṣūl al-Dīn, Abū al-Muʿīn al-Nasafī’s Tabṣirat al-Adilla and Najm al-Dīn al-Nasafī’s al-ʿAqāʾid, widely taught with al-Taftāzānī’s commentary. The school sees its method as continuing Abū Ḥanīfa’s positions."],
    de: ["Welche Hauptwerke der Māturīditen gibt es, und wie steht die Schule zu Abū Ḥanīfa?", ["Kitāb at-Tauḥīd und Taʾwīlāt Ahl as-Sunna von al-Māturīdī, mit späteren systematischen Werken von an-Nasafī und al-Bazdawī; die Schule sieht sich als Glaubensausdruck der ḥanafitischen Tradition", "Al-Muwaṭṭaʾ von Mālik; die Schule folgt Mālik", "Ar-Risāla von aš-Šāfiʿī; die Schule folgt aš-Šāfiʿī", "Nahǧ al-Balāġa; die Schule ist schiitisch"], "Abū Manṣūr al-Māturīdī (gest. 333 n. H.) aus Samarkand schrieb Kitāb at-Tauḥīd zum Glauben und Taʾwīlāt Ahl as-Sunna zur Koranauslegung. Spätere māturiditische Werke sind al-Bazdawīs Uṣūl ad-Dīn, Abū l-Muʿīn an-Nasafīs Tabṣirat al-Adilla und Naǧm ad-Dīn an-Nasafīs al-ʿAqāʾid, weithin mit al-Taftāzānīs Kommentar gelehrt. Die Schule sieht ihre Methode als Fortführung der Positionen Abū Ḥanīfas."],
    ar: ["ما أهم مؤلفات الماتريدية وما صلة المدرسة بأبي حنيفة؟", ["«كتاب التوحيد» و«تأويلات أهل السنة» للماتريدي ثم مؤلفات منهجية متأخرة للنسفي والبزدوي، وترى المدرسة نفسها التعبير العقدي عن التقليد الحنفي", "«الموطأ» لمالك وتتبع المدرسة مالكًا", "«الرسالة» للشافعي وتتبع المدرسة الشافعي", "«نهج البلاغة» والمدرسة شيعية", ], "ألّف أبو منصور الماتريدي (ت 333هـ) السمرقندي «كتاب التوحيد» في العقيدة و«تأويلات أهل السنة» في التفسير، ومن مؤلفات الماتريدية المتأخرة «أصول الدين» للبزدوي و«تبصرة الأدلة» لأبي المعين النسفي و«العقائد» لنجم الدين النسفي المشروحة بشرح التفتازاني، وتعد المدرسة منهجها امتدادًا لمواقف أبي حنيفة."] },

  { id: "xaq-026", s: "aqidah", g: 4, d: 6, t: ["creeds", "tahawiyya", "nasafiyya"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya; al-Nasafī, al-ʿAqāʾid; al-Sanūsī, Umm al-Barāhīn; Ibn Qudāma, Lumʿat al-Iʿtiqād; al-Ghazālī, al-Iqtiṣād fī al-Iʿtiqād",
    en: ["Which statement correctly matches creedal texts with traditions or authors?", ["al-ʿAqīda al-Ṭaḥāwiyya (al-Ṭaḥāwī, a Ḥanafī, accepted across Sunni traditions), al-ʿAqāʾid al-Nasafiyya (Māturīdī), Umm al-Barāhīn (al-Sanūsī, Ashʿarī) and Lumʿat al-Iʿtiqād (Ibn Qudāma, Ḥanbalī/Atharī)", "al-Ṭaḥāwiyya is a Muʿtazilī text; Umm al-Barāhīn is Ḥanbalī", "Lumʿat al-Iʿtiqād is Māturīdī; al-Nasafiyya is Atharī", "All four are Shīʿī"], "Abū Jaʿfar al-Ṭaḥāwī (d. 321 AH) wrote his short creed to state the beliefs of Abū Ḥanīfa and his students, and it is accepted widely. The Nasafiyya is the standard Māturīdī text; al-Sanūsī (d. 895 AH) wrote Umm al-Barāhīn in the Ashʿarī tradition; Ibn Qudāma’s Lumʿat al-Iʿtiqād is a Ḥanbalī/Atharī creed. Al-Ghazālī’s al-Iqtiṣād is a major Ashʿarī work."],
    de: ["Welche Aussage ordnet Glaubenstexte Traditionen oder Autoren richtig zu?", ["Al-ʿAqīda aṭ-Ṭaḥāwiyya (aṭ-Ṭaḥāwī, Ḥanafit, über die sunnitischen Traditionen hinweg anerkannt), al-ʿAqāʾid an-Nasafiyya (Māturīdī), Umm al-Barāhīn (as-Sanūsī, Ašʿarit) und Lumʿat al-Iʿtiqād (Ibn Qudāma, Ḥanbalit/Atharīt)", "Aṭ-Ṭaḥāwiyya ist ein muʿtazilitischer Text; Umm al-Barāhīn ist ḥanbalitisch", "Lumʿat al-Iʿtiqād ist māturiditisch; an-Nasafiyya ist atharitisch", "Alle vier sind schiitisch"], "Abū Ǧaʿfar aṭ-Ṭaḥāwī (gest. 321 n. H.) schrieb sein kurzes Bekenntnis, um die Überzeugungen Abū Ḥanīfas und seiner Schüler darzulegen, und es ist weithin anerkannt. Die Nasafiyya ist der māturiditische Standardtext; as-Sanūsī (gest. 895 n. H.) schrieb Umm al-Barāhīn in der ašʿaritischen Tradition; Ibn Qudāmas Lumʿat al-Iʿtiqād ist ein ḥanbalitisch-atharitisches Bekenntnis. Al-Ġazālīs al-Iqtiṣād ist ein bedeutendes ašʿaritisches Werk."],
    ar: ["أي عبارة تقرن النصوص العقدية بتقاليدها أو مؤلفيها على الوجه الصحيح؟", ["العقيدة الطحاوية (الطحاوي حنفي ومقبولة عند السنة)، والعقائد النسفية (ماتريدي)، وأم البراهين (السنوسي أشعري)، ولمعة الاعتقاد (ابن قدامة حنبلي أثري)", "الطحاوية معتزلية وأم البراهين حنبلية", "لمعة الاعتقاد ماتريدية والنسفية أثرية", "الأربعة شيعية"], "كتب أبو جعفر الطحاوي (ت 321هـ) عقيدته المختصرة لبيان اعتقاد أبي حنيفة وصاحبيه فتلقاها أهل السنة بالقبول، والنسفية متن الماتريدية المعتمد، وألّف السنوسي (ت 895هـ) «أم البراهين» على طريقة الأشاعرة، و«لمعة الاعتقاد» لابن قدامة عقيدة حنبلية أثرية، و«الاقتصاد» للغزالي من أهم كتب الأشاعرة."] },

  { id: "xaq-027", s: "aqidah", g: 4, d: 7, t: ["ashari", "kalam-history", "juwayni-ghazali"], tr: ["ashari"], src: "al-Subkī, Ṭabaqāt al-Shāfiʿiyya; al-Juwaynī, al-Irshād; al-Ghazālī, Tahāfut al-Falāsifa and al-Munqidh min al-Ḍalāl; al-Rāzī, Muḥaṣṣal Afkār al-Mutaqaddimīn",
    en: ["Which sequence of authors marks the development of Ashʿarī kalām?", ["al-Bāqillānī, al-Juwaynī, al-Ghazālī and Fakhr al-Dīn al-Rāzī", "Ibn Ḥazm, Ibn Rushd, Ibn Khaldūn and Ibn Khallikān", "Mālik, Abū Ḥanīfa, al-Shāfiʿī and Aḥmad", "Sībawayh, al-Mubarrad, Ibn Jinnī and Ibn Mālik"], "Al-Bāqillānī (d. 403 AH) set Ashʿarī kalām on atomist and rational foundations. Al-Juwaynī (d. 478 AH) wrote al-Irshād and al-ʿAqīda al-Niẓāmiyya, his student al-Ghazālī (d. 505 AH) wrote al-Iqtiṣād and Tahāfut al-Falāsifa against the philosophers, and al-Rāzī (d. 606 AH) brought philosophy and kalām together. Later scholars wrote commentaries on their works, and Ibn Rushd’s Tahāfut al-Tahāfut answered al-Ghazālī."],
    de: ["Welche Autorenreihe markiert die Entwicklung des ašʿaritischen Kalām?", ["Al-Bāqillānī, al-Ǧuwainī, al-Ġazālī und Faḫr ad-Dīn ar-Rāzī", "Ibn Ḥazm, Ibn Rušd, Ibn Ḫaldūn und Ibn Ḫallikān", "Mālik, Abū Ḥanīfa, aš-Šāfiʿī und Aḥmad", "Sībawaih, al-Mubarrad, Ibn Ǧinnī und Ibn Mālik"], "Al-Bāqillānī (gest. 403 n. H.) stellte den ašʿaritischen Kalām auf atomistische und rationale Grundlagen. Al-Ǧuwainī (gest. 478 n. H.) schrieb al-Iršād und al-ʿAqīda an-Niẓāmiyya, sein Schüler al-Ġazālī (gest. 505 n. H.) schrieb al-Iqtiṣād und Tahāfut al-Falāsifa gegen die Philosophen, und ar-Rāzī (gest. 606 n. H.) verband Philosophie und Kalām. Spätere Gelehrte schrieben Kommentare zu ihren Werken, und Ibn Rušds Tahāfut at-Tahāfut antwortete al-Ġazālī."],
    ar: ["أي تسلسل للمؤلفين يمثل تطور الكلام الأشعري؟", ["الباقلاني فالجويني فالغزالي ففخر الدين الرازي", "ابن حزم فابن رشد فابن خلدون فابن خلكان", "مالك وأبو حنيفة والشافعي وأحمد", "سيبويه والمبرد وابن جني وابن مالك"], "أقام الباقلاني (ت 403هـ) الكلام الأشعري على أسس ذرية وعقلية، وألّف الجويني (ت 478هـ) «الإرشاد» و«العقيدة النظامية»، وألّف تلميذه الغزالي (ت 505هـ) «الاقتصاد» و«تهافت الفلاسفة» ردًّا على الفلاسفة، وجمع الرازي (ت 606هـ) بين الفلسفة والكلام، وكتب المتأخرون عليها شروحًا، وردّ ابن رشد على الغزالي في «تهافت التهافت»."] },

  { id: "xaq-028", s: "aqidah", g: 4, d: 7, t: ["philosophy", "tahafut", "world-eternity"], tr: ["ashari", "comparative"], src: "al-Ghazālī, Tahāfut al-Falāsifa; Ibn Rushd, Tahāfut al-Tahāfut and Faṣl al-Maqāl; al-Munqidh min al-Ḍalāl",
    en: ["On which three questions did al-Ghazālī declare the philosophers disbelievers in Tahāfut al-Falāsifa?", ["The eternity of the world, God’s knowledge of only universals, and the denial of bodily resurrection", "The existence of angels, jinn and Satan", "The number of prayers, the amount of zakāt and the months of the year", "The authority of the Quran, the Sunna and consensus"], "Al-Ghazālī in Tahāfut al-Falāsifa discussed twenty questions, and said the philosophers should be declared unbelievers for three: the claim that the world is eternal, that God knows only universals (not particulars), and the denial of bodily resurrection. In the rest, he called them innovators. Ibn Rushd replied in Tahāfut al-Tahāfut and Faṣl al-Maqāl, disputing the representation of philosophical positions and the call of takfīr."],
    de: ["In welchen drei Fragen erklärte al-Ġazālī die Philosophen in Tahāfut al-Falāsifa für ungläubig?", ["Die Ewigkeit der Welt, Gottes Wissen nur von Allgemeinem und die Leugnung der leiblichen Auferstehung", "Die Existenz von Engeln, Ǧinn und Satan", "Die Zahl der Gebete, die Höhe der Zakāt und die Monate des Jahres", "Die Autorität von Koran, Sunna und Konsens"], "Al-Ġazālī erörterte in Tahāfut al-Falāsifa zwanzig Fragen und sagte, die Philosophen seien in dreien für ungläubig zu erklären: der Behauptung, die Welt sei ewig, Gott kenne nur Allgemeines (nicht Einzelnes), und der Leugnung der leiblichen Auferstehung. Im Übrigen nannte er sie Neuerer. Ibn Rušd antwortete in Tahāfut at-Tahāfut und Faṣl al-Maqāl, bestritt die Darstellung der philosophischen Positionen und den Aufruf zum Takfīr."],
    ar: ["في أي ثلاث مسائل كفّر الغزالي الفلاسفة في «تهافت الفلاسفة»؟", ["قدم العالم وأن الله لا يعلم إلا الكليات وإنكار حشر الأجساد", "وجود الملائكة والجن والشيطان", "عدد الصلوات ومقدار الزكاة وأشهر السنة", "حجية القرآن والسنة والإجماع"], "ناقش الغزالي في «تهافت الفلاسفة» عشرين مسألة وقال بتكفير الفلاسفة في ثلاث: القول بقدم العالم وبأن الله يعلم الكليات دون الجزئيات وإنكار حشر الأجساد، وبدّعهم في الباقي، وردّ ابن رشد في «تهافت التهافت» و«فصل المقال» منازعًا في تصوير مقالاتهم وفي دعوى التكفير."] },

  { id: "xaq-029", s: "aqidah", g: 4, d: 6, t: ["sufism", "kalam", "tasawwuf-aqidah"], tr: ["comparative"], src: "al-Qushayrī, al-Risāla; al-Ghazālī, Iḥyāʾ ʿUlūm al-Dīn; Ibn Taymiyya, Majmūʿ al-Fatāwā; al-Junayd, Rasāʾil",
    en: ["What is the classical Sunni attitude of Sufi manuals like al-Qushayrī’s Risāla towards creed?", ["They present Sufism as grounded in the creed of Ahl al-Sunna and the Sharia, citing al-Junayd’s saying that the path is bound by the Quran and Sunna, while critics such as Ibn Taymiyya distinguished sound Sufis from excesses", "They teach that the Sharia is unnecessary", "They reject belief in God", "They have no connection to creed"], "Al-Qushayrī (d. 465 AH) opens the Risāla with a creedal statement in the Ashʿarī tradition. Al-Junayd of Baghdad is quoted as saying that his knowledge is bound by the Quran and Sunna. Al-Ghazālī built Iḥyāʾ on the same grounds. Ibn Taymiyya praised the early Sufis who held to the Sharia but criticised ideas such as waḥdat al-wujūd and claims to exemption from the law."],
    de: ["Was ist die klassische sunnitische Haltung von Sufi-Handbüchern wie al-Qušairīs Risāla zum Glauben?", ["Sie stellen den Sufismus als im Glauben der Ahl as-Sunna und der Scharia gegründet dar und zitieren al-Ǧunaids Wort, der Weg sei an Koran und Sunna gebunden, während Kritiker wie Ibn Taimiyya gesunde Sufis von Auswüchsen unterschieden", "Sie lehren, die Scharia sei unnötig", "Sie lehnen den Glauben an Gott ab", "Sie haben keinen Bezug zum Glauben"], "Al-Qušairī (gest. 465 n. H.) eröffnet die Risāla mit einer Glaubenserklärung in der ašʿaritischen Tradition. Von al-Ǧunaid von Bagdad wird gesagt, sein Wissen sei an Koran und Sunna gebunden. Al-Ġazālī baute das Iḥyāʾ auf demselben Grund. Ibn Taimiyya lobte die frühen Sufis, die an der Scharia festhielten, kritisierte aber Ideen wie Waḥdat al-wuǧūd und Ansprüche auf Befreiung vom Gesetz."],
    ar: ["ما الموقف السني الكلاسيكي لكتب التصوف كـ«الرسالة» للقشيري من العقيدة؟", ["تعرض التصوف على أصل عقيدة أهل السنة والشريعة وتنقل قول الجنيد أن الطريق مقيد بالكتاب والسنة، وفرق نقاد كابن تيمية بين الصوفية الصحيحة والغلو", "تعلّم أن الشريعة غير لازمة", "ترفض الإيمان بالله", "لا صلة لها بالعقيدة"], "يفتتح القشيري (ت 465هـ) «الرسالة» ببيان عقدي على طريقة الأشاعرة، وينقل عن الجنيد البغدادي أن علمه مقيد بالكتاب والسنة، وبنى الغزالي «الإحياء» على الأساس نفسه، وأثنى ابن تيمية على الصوفية الأوائل الملتزمين بالشريعة وانتقد أفكارًا كوحدة الوجود ودعوى السقوط عن التكليف."] },

  { id: "xaq-030", s: "aqidah", g: 4, d: 7, t: ["imamate", "conditions", "sunni-shia"], tr: ["comparative", "sunni"], src: "al-Māwardī, al-Aḥkām al-Sulṭāniyya; al-Ījī, al-Mawāqif; al-Nasafī, al-ʿAqāʾid; Ibn Taymiyya, Minhāj al-Sunna",
    en: ["How do Sunni creeds and Shīʿī thought differ about the imamate?", ["Sunnis treat the imamate as a matter of public interest, established by choice or consultation with conditions such as Qurashī descent in the common view; the Twelver Shīʿa hold that it is a matter of faith, designated by text and ʿiṣma", "Both hold identical views", "Sunnis hold the imam is infallible; the Shīʿa deny it", "Both deny any role for a leader"], "Sunni creeds (al-Nasafī, al-Ījī) treat the imamate as a branch matter and hold that it is established by pledge, consultation or designation, with al-Māwardī listing conditions (justice, knowledge, competence, Qurashī lineage in the majority view). The Twelver Shīʿa hold that the imamate is a pillar of faith, that imams are designated and protected from error, starting with ʿAlī. This divide goes back to the Saqīfa."],
    de: ["Wie unterscheiden sich sunnitische Bekenntnisse und schiitisches Denken beim Imamat?", ["Sunniten behandeln das Imamat als Frage des Gemeinwohls, durch Wahl oder Beratung mit Bedingungen wie qurašitischer Abstammung nach der üblichen Ansicht begründet; die Zwölferschia hält es für eine Glaubenssache, durch Text bestimmt und mit ʿiṣma verbunden", "Beide vertreten identische Ansichten", "Sunniten halten den Imam für unfehlbar; die Schia bestreitet es", "Beide bestreiten jede Rolle eines Führers"], "Sunnitische Bekenntnisse (an-Nasafī, al-Īǧī) behandeln das Imamat als Nebenfrage und halten, es werde durch Treueid, Beratung oder Bestimmung begründet, wobei al-Māwardī Bedingungen aufführt (Gerechtigkeit, Wissen, Fähigkeit, nach Mehrheitsansicht qurašitische Abstammung). Die Zwölferschia hält das Imamat für eine Säule des Glaubens, die Imame für bestimmt und vor Irrtum geschützt, beginnend mit ʿAlī. Diese Trennung geht auf die Saqīfa zurück."],
    ar: ["كيف تختلف العقائد السنية والفكر الشيعي في الإمامة؟", ["يعدها أهل السنة من مسائل المصلحة العامة تثبت بالاختيار أو الشورى بشروط كالنسب القرشي في الرأي الشائع، وترى الإمامية الاثنا عشرية أنها من أصول الدين تثبت بالنص والعصمة", "رأيهما متطابق", "السنة يرون الإمام معصومًا والشيعة ينفون ذلك", "كلاهما ينفي دور القائد"], "تعد العقائد السنية (النسفي والإيجي) الإمامة من الفروع وتقول إنها تثبت بالبيعة أو الشورى أو العهد، ويذكر الماوردي شروطها (العدالة والعلم والكفاية والنسب القرشي عند الأكثر)، وترى الإمامية الاثنا عشرية أنها من أصول الدين وأن الأئمة منصوص عليهم معصومون ابتداءً بعلي، ويعود هذا الخلاف إلى السقيفة."] },

  { id: "xaq-031", s: "aqidah", g: 4, d: 7, t: ["bidah", "types", "izz-ibn-abd-al-salam"], tr: ["comparative", "shafii", "maliki", "hanbali"], src: "Ibn ʿAbd al-Salām, Qawāʿid al-Aḥkām; al-Shāfiʿī as quoted in Ḥilyat al-Awliyāʾ; al-Shāṭibī, al-Iʿtiṣām; Ibn Rajab, Jāmiʿ al-ʿUlūm wa-l-Ḥikam",
    en: ["How do scholars divide innovation (bidʿa), and who objected to the division?", ["Al-Shāfiʿī and al-ʿIzz ibn ʿAbd al-Salām distinguished good and bad innovation (and five rulings), while al-Shāṭibī and Ibn Rajab held that every innovation in religion is misguidance and the ‘good’ cases are linguistic or fall under sunna", "No scholar discussed innovation", "All agree innovations are lawful", "All agree that innovation concerns only food"], "Al-Shāfiʿī is quoted as dividing innovation into the praiseworthy (agreeing with Sunna) and blameworthy. Al-ʿIzz ibn ʿAbd al-Salām in Qawāʿid al-Aḥkām applied five rulings to innovations. Al-Shāṭibī in al-Iʿtiṣām and Ibn Rajab argued that the hadith ‘every innovation is misguidance’ is general, and the examples of ‘good innovation’ either fall under the Sunna or are innovations only in a linguistic sense."],
    de: ["Wie teilen Gelehrte die Neuerung (bidʿa) ein, und wer widersprach der Einteilung?", ["Aš-Šāfiʿī und al-ʿIzz ibn ʿAbd as-Salām unterschieden gute und schlechte Neuerung (und fünf Urteile), während aš-Šāṭibī und Ibn Raǧab hielten, jede Neuerung in der Religion sei Irreführung und die ‚guten‘ Fälle seien sprachlich oder fielen unter die Sunna", "Kein Gelehrter erörterte Neuerung", "Alle stimmen überein, dass Neuerungen erlaubt sind", "Alle stimmen überein, dass Neuerung nur Speisen betrifft"], "Von aš-Šāfiʿī wird angeführt, er habe die Neuerung in lobenswerte (mit der Sunna übereinstimmende) und tadelnswerte eingeteilt. Al-ʿIzz ibn ʿAbd as-Salām wandte in Qawāʿid al-Aḥkām fünf Urteile auf Neuerungen an. Aš-Šāṭibī in al-Iʿtiṣām und Ibn Raǧab argumentierten, der Hadith ‚jede Neuerung ist Irreführung‘ sei allgemein, und die Beispiele ‚guter Neuerung‘ fielen entweder unter die Sunna oder seien nur im sprachlichen Sinn Neuerungen."],
    ar: ["كيف يقسم العلماء البدعة ومن اعترض على التقسيم؟", ["قسّم الشافعي والعز بن عبد السلام البدعة إلى حسنة وسيئة (وإلى أحكام خمسة)، وقال الشاطبي وابن رجب إن كل بدعة في الدين ضلالة وإن الحسنة منها لغوية أو داخلة في السنة", "لم يبحث عالم البدعة", "اتفق الجميع على إباحة البدع", "اتفق الجميع على أن البدعة في الطعام فقط"], "يُنقل عن الشافعي تقسيم البدعة إلى محمودة وافقت السنة ومذمومة، وطبّق العز بن عبد السلام في «قواعد الأحكام» الأحكام الخمسة على البدع، وقرر الشاطبي في «الاعتصام» وابن رجب أن حديث «كل بدعة ضلالة» عام وأن أمثلة البدعة الحسنة إما داخلة في السنة أو بدعة بالمعنى اللغوي فقط."] },

  { id: "xaq-032", s: "aqidah", g: 4, d: 6, t: ["tawassul", "intercession-by-the-righteous"], tr: ["comparative", "hanbali", "shafii", "hanafi"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-istisqāʾ (ʿUmar and al-ʿAbbās); Ibn Taymiyya, Qāʿida Jalīla fī al-Tawassul wa-l-Wasīla; al-Subkī, Shifāʾ al-Siqām",
    en: ["How did the scholars treat tawassul (seeking means through the righteous in supplication)?", ["All accept tawassul through the Prophet’s supplication and one’s own good deeds; they differ on tawassul by the person or status of a righteous being, which many Shāfiʿīs and Ḥanafīs allowed and Ibn Taymiyya and many Ḥanbalīs restricted", "All scholars forbade all tawassul", "All scholars allowed worship of saints", "Nobody discussed tawassul"], "The report in al-Bukhārī of ʿUmar asking al-ʿAbbās to pray for rain is cited as tawassul by a living righteous person’s supplication, accepted by all. Tawassul by the status of a person or by their name after death is allowed by many scholars (al-Subkī, many Shāfiʿīs and Ḥanafīs) and held impermissible or unproven by Ibn Taymiyya and others, who regarded asking the dead as a serious matter. Treatises exist on both sides."],
    de: ["Wie behandelten die Gelehrten das Tawassul (Mittelsuche über Rechtschaffene im Bittgebet)?", ["Alle akzeptieren Tawassul durch das Bittgebet des Propheten und die eigenen guten Taten; sie unterscheiden sich beim Tawassul durch die Person oder Stellung eines Rechtschaffenen, den viele Šāfiʿiten und Ḥanafiten erlaubten und Ibn Taimiyya und viele Ḥanbaliten einschränkten", "Alle Gelehrten verboten jedes Tawassul", "Alle Gelehrten erlaubten die Anbetung von Heiligen", "Niemand erörterte Tawassul"], "Der Bericht bei al-Buḫārī, wie ʿUmar al-ʿAbbās bat, um Regen zu beten, wird als Tawassul durch das Bittgebet eines lebenden Rechtschaffenen angeführt, von allen akzeptiert. Tawassul durch die Stellung einer Person oder ihren Namen nach dem Tod erlauben viele Gelehrte (as-Subkī, viele Šāfiʿiten und Ḥanafiten), und Ibn Taimiyya und andere hielten es für unzulässig oder unbelegt und sahen das Bitten der Toten als ernste Sache. Abhandlungen gibt es auf beiden Seiten."],
    ar: ["كيف عالج العلماء التوسل (طلب الوسيلة بالصالحين في الدعاء)؟", ["يقبل الجميع التوسل بدعاء النبي ﷺ وبالأعمال الصالحة، ويختلفون في التوسل بذات الصالح أو جاهه، فأجازه كثير من الشافعية والحنفية وقيّده ابن تيمية وكثير من الحنابلة", "منع كل العلماء كل أنواع التوسل", "أجاز كل العلماء عبادة الأولياء", "لم يبحث أحد التوسل"], "يُستدل بخبر البخاري في استسقاء عمر بالعباس على التوسل بدعاء حي صالح وهو مقبول عند الجميع، أما التوسل بجاه الشخص أو اسمه بعد الموت فأجازه كثير من العلماء (السبكي وكثير من الشافعية والحنفية) ورآه ابن تيمية وغيره غير جائز أو غير ثابت وشدد في سؤال الأموات، وفي الجانبين رسائل."] },

  { id: "xaq-033", s: "aqidah", g: 4, d: 7, t: ["miracles", "magic", "sihr-reality"], tr: ["comparative", "ashari"], src: "al-Ṭabarī, Tafsīr, on sūrat al-Baqara; al-Jaṣṣāṣ, Aḥkām al-Qurʾān; al-Rāzī, al-Tafsīr al-Kabīr; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["What disagreement is there on the reality of magic (siḥr) among the schools?", ["Most Sunni scholars held that magic has a real effect by God’s permission, while some Muʿtazilīs and certain Ḥanafīs such as al-Jaṣṣāṣ held it to be mainly illusion and trickery", "All held that magic is impossible", "All held that magic changes the nature of things in all cases", "Nobody discussed magic"], "Sunni scholars, citing the account of the Prophet being affected by magic in al-Bukhārī and Muslim, held that magic is real and affects bodies and hearts by God’s permission. Some of the Muʿtazila and scholars such as al-Jaṣṣāṣ thought it mostly consists of deception (takhyīl), and disagreed over details such as its ability to cause illness. The jurists also differ on the penalty for the magician."],
    de: ["Welche Meinungsverschiedenheit besteht unter den Schulen über die Wirklichkeit der Magie (siḥr)?", ["Die meisten sunnitischen Gelehrten hielten, Magie habe mit Gottes Erlaubnis eine wirkliche Wirkung, während manche Muʿtaziliten und gewisse Ḥanafiten wie al-Ǧaṣṣāṣ sie hauptsächlich für Täuschung und Trick hielten", "Alle hielten Magie für unmöglich", "Alle hielten, Magie verändere in allen Fällen die Natur der Dinge", "Niemand erörterte Magie"], "Sunnitische Gelehrte, die sich auf den Bericht bei al-Buḫārī und Muslim berufen, der Prophet sei von Magie betroffen gewesen, hielten Magie für wirklich und auf Körper und Herzen mit Gottes Erlaubnis wirkend. Manche Muʿtaziliten und Gelehrte wie al-Ǧaṣṣāṣ meinten, sie bestehe meist aus Täuschung (taḫyīl), und waren in Einzelheiten uneins, etwa ob sie Krankheit verursachen kann. Auch die Juristen unterscheiden sich in der Strafe für den Magier."],
    ar: ["ما الخلاف في حقيقة السحر بين المذاهب؟", ["رأى أكثر علماء السنة أن للسحر حقيقة وتأثيرًا بإذن الله، ورأى بعض المعتزلة وبعض الحنفية كالجصاص أنه في الغالب تخييل وخداع", "رأى الجميع أن السحر مستحيل", "رأى الجميع أن السحر يقلب الحقائق دائمًا", "لم يبحث أحد السحر"], "قال علماء السنة محتجين بخبر تأثر النبي ﷺ بالسحر في البخاري ومسلم إن للسحر حقيقة ويؤثر في الأبدان والقلوب بإذن الله، وذهب بعض المعتزلة وعلماء كالجصاص إلى أنه في الغالب تخييل، واختلفوا في تفاصيل كإمكان تسببه في المرض، وللفقهاء خلاف في عقوبة الساحر."] },

  { id: "xaq-034", s: "aqidah", g: 4, d: 6, t: ["jinn", "angels", "unseen"], src: "Ibn Taymiyya, Majmūʿ al-Fatāwā (Idāḥ al-Dalāla fī ʿUmūm al-Risāla); al-Ṭabarī, Tafsīr; Ibn Kathīr, Tafsīr, on sūrat al-Jinn; al-Nasafī, al-ʿAqāʾid",
    en: ["What do the Sunni creeds say about the nature of angels and jinn, and which difference is noted between Iblīs and the angels?", ["Angels are created from light and do not disobey, while jinn are created from fire and are accountable; the debate on whether Iblīs was an angel or a jinn is settled by most Sunni scholars as a jinn, according to the verse naming him from the jinn", "Angels are created from fire and jinn from light", "Jinn and angels are the same", "Neither is accountable"], "The creeds affirm belief in angels, created of light and in worship, and jinn, created from smokeless fire, who are accountable and include believers and unbelievers. Al-Ḥasan al-Baṣrī and many others held that Iblīs was never an angel. Some commentators in the early period held he was an angel, drawing on the context of the command to prostrate, but most classical Sunni exegetes favoured the first view."],
    de: ["Was sagen die sunnitischen Bekenntnisse über die Natur von Engeln und Ǧinn, und welcher Unterschied wird zwischen Iblīs und den Engeln vermerkt?", ["Engel sind aus Licht erschaffen und gehorchen immer, Ǧinn sind aus Feuer erschaffen und verantwortlich; ob Iblīs ein Engel oder Ǧinn war, wird von den meisten sunnitischen Gelehrten als Ǧinn entschieden, nach dem Vers, der ihn zu den Ǧinn zählt", "Engel sind aus Feuer und Ǧinn aus Licht erschaffen", "Ǧinn und Engel sind dasselbe", "Keines von beiden ist verantwortlich"], "Die Bekenntnisse bejahen den Glauben an Engel, aus Licht erschaffen und im Gottesdienst, und an Ǧinn, aus rauchlosem Feuer erschaffen, die verantwortlich sind und Gläubige und Ungläubige umfassen. Al-Ḥasan al-Baṣrī und viele andere hielten, Iblīs sei nie ein Engel gewesen. Einige Kommentatoren der frühen Zeit hielten ihn für einen Engel, gestützt auf den Zusammenhang des Befehls zur Niederwerfung, doch die meisten klassischen sunnitischen Exegeten bevorzugten die erste Ansicht."],
    ar: ["ماذا تقول العقائد السنية في طبيعة الملائكة والجن وما الفرق المذكور بين إبليس والملائكة؟", ["الملائكة مخلوقون من نور لا يعصون والجن من نار ومكلفون، والمسألة هل إبليس ملك أم جني رجح أكثر علماء السنة أنه من الجن بنص الآية التي عدّته منهم", "الملائكة من نار والجن من نور", "الجن والملائكة شيء واحد", "كلاهما غير مكلف"], "تثبت العقائد الإيمان بالملائكة المخلوقين من نور المتعبدين وبالجن المخلوقين من نار لا دخان فيها وهم مكلفون فيهم المؤمن والكافر، وقال الحسن البصري وكثيرون إن إبليس لم يكن ملكًا قط، وذهب بعض المفسرين الأوائل إلى أنه ملك بحسب سياق الأمر بالسجود، لكن أكثر المفسرين السنة الكلاسيكيين رجحوا الأول."] },

  { id: "xaq-035", s: "aqidah", g: 4, d: 7, t: ["abraham-parents", "fatra", "ahl-al-fatra"], tr: ["comparative", "sunni"], src: "Muslim, Ṣaḥīḥ, Kitāb al-janāʾiz; al-Suyūṭī, Masālik al-Ḥunafāʾ; Ibn Kathīr, Tafsīr; al-Ṭabarī, Tafsīr",
    en: ["What do scholars say about the fate of those who died in the interval between messengers (ahl al-fatra)?", ["Scholars differed: some held they are not punished until a message reaches them, others that they will be tested in the hereafter, and others that they are judged by what they could know by reason; reports exist for each view", "All scholars agree they are certainly in Paradise", "All scholars agree they are certainly in the Fire", "Nobody discussed this"], "The question of those who never received a message is treated through the verse that God does not punish until He sends a messenger, with the reports of testing in the hereafter in Aḥmad and others. Ashʿarīs generally hold no punishment without a message; the Māturīdīs hold that some knowledge of God is obligatory by reason; the Atharīs prefer the report of testing. A report in Muslim concerning the Prophet’s father is also discussed, with al-Suyūṭī writing treatises on the topic."],
    de: ["Was sagen Gelehrte über das Schicksal derer, die in der Zeit zwischen Gesandten starben (ahl al-fatra)?", ["Die Gelehrten waren uneins: Einige hielten, sie würden nicht bestraft, bis eine Botschaft sie erreicht, andere, sie würden im Jenseits geprüft, und andere, sie würden nach dem beurteilt, was sie durch Vernunft wissen konnten; Berichte gibt es für jede Ansicht", "Alle Gelehrten stimmen überein, dass sie sicher im Paradies sind", "Alle Gelehrten stimmen überein, dass sie sicher im Feuer sind", "Niemand erörterte dies"], "Die Frage derer, die nie eine Botschaft erhielten, wird über den Vers behandelt, dass Gott nicht straft, bis Er einen Gesandten schickt, sowie über die Berichte von der Prüfung im Jenseits bei Aḥmad und anderen. Die Ašʿariten halten im Allgemeinen, dass es ohne Botschaft keine Strafe gibt; die Māturīditen, dass etwas Wissen von Gott durch Vernunft verpflichtend ist; die Atharīten bevorzugen den Bericht von der Prüfung. Ein Bericht bei Muslim über den Vater des Propheten wird ebenfalls erörtert, wobei as-Suyūṭī Abhandlungen zum Thema schrieb."],
    ar: ["ماذا يقول العلماء في مصير من ماتوا في فترة ما بين الرسل (أهل الفترة)؟", ["اختلفوا: قيل لا يعذبون حتى تبلغهم رسالة، وقيل يُمتحنون في الآخرة، وقيل يحاسبون بما أدركوه بعقولهم، ولكل قول روايات", "اتفق العلماء على أنهم في الجنة قطعًا", "اتفق العلماء على أنهم في النار قطعًا", "لم يبحث أحد المسألة"], "تُعالج مسألة من لم تبلغهم رسالة بالآية أن الله لا يعذب حتى يبعث رسولًا مع أخبار الامتحان في الآخرة عند أحمد وغيره، ويرى الأشاعرة عمومًا ألا عذاب قبل البعثة، ويرى الماتريدية أن معرفة الله واجبة بالعقل في الجملة، ويفضل أهل الأثر خبر الامتحان، وتُبحث رواية مسلم في والد النبي ﷺ أيضًا وللسيوطي رسائل في الموضوع."] },

  { id: "xaq-036", s: "aqidah", g: 4, d: 6, t: ["signs-of-the-hour", "mahdi", "dajjal"], tr: ["comparative", "sunni"], src: "Muslim, Ṣaḥīḥ, Kitāb al-fitan wa-ashrāṭ al-sāʿa (ḥadīth Ḥudhayfa); Abū Dāwūd, Sunan, Kitāb al-mahdī; Ibn Khaldūn, Muqaddima; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["Which are the major signs of the Hour in the report of Ḥudhayfa ibn Asīd in Muslim, and what is the scholarly discussion about the Mahdī?", ["Smoke, the Dajjāl, the beast, the rising of the sun from the west, the descent of ʿĪsā, Gog and Magog, three landslides and a fire from Yemen; the Mahdī is not in the Ṣaḥīḥayn, and scholars such as Ibn Khaldūn weakened the reports while others like Ibn Ḥajar and al-Suyūṭī considered them well-supported", "Only an earthquake and a flood", "Only the Mahdī", "The report names no signs"], "Muslim records Ḥudhayfa ibn Asīd’s report of ten signs: the smoke, the Dajjāl, the beast, the sun rising from its place of setting, the descent of ʿĪsā, Yājūj and Mājūj, three landslides (east, west and Arabian Peninsula) and a fire from Yemen. The Mahdī reports are in Abū Dāwūd, al-Tirmidhī and others, and Ibn Khaldūn criticised them in the Muqaddima, while many scholars held the reports to be collectively supported."],
    de: ["Welche sind die großen Zeichen der Stunde im Bericht von Ḥuḏaifa ibn Asīd bei Muslim, und wie wird der Mahdī von den Gelehrten erörtert?", ["Rauch, der Daǧǧāl, das Tier, der Aufgang der Sonne im Westen, das Herabkommen ʿĪsās, Gog und Magog, drei Erdrutsche und ein Feuer aus dem Jemen; der Mahdī steht nicht in den Ṣaḥīḥain, und Gelehrte wie Ibn Ḫaldūn hielten die Berichte für schwach, während andere wie Ibn Ḥaǧar und as-Suyūṭī sie für gut gestützt hielten", "Nur ein Erdbeben und eine Flut", "Nur der Mahdī", "Der Bericht nennt keine Zeichen"], "Muslim überliefert Ḥuḏaifa ibn Asīds Bericht von zehn Zeichen: Rauch, der Daǧǧāl, das Tier, der Aufgang der Sonne dort, wo sie untergeht, das Herabkommen ʿĪsās, Yāǧūǧ und Māǧūǧ, drei Erdrutsche (im Osten, Westen und auf der Arabischen Halbinsel) und ein Feuer aus dem Jemen. Die Mahdī-Berichte stehen bei Abū Dāwūd, at-Tirmiḏī und anderen, und Ibn Ḫaldūn kritisierte sie in der Muqaddima, während viele Gelehrte die Berichte insgesamt für gestützt hielten."],
    ar: ["ما العلامات الكبرى للساعة في حديث حذيفة بن أسيد في مسلم وما النقاش العلمي في المهدي؟", ["الدخان والدجال والدابة وطلوع الشمس من مغربها ونزول عيسى ويأجوج ومأجوج وثلاثة خسوف ونار من اليمن، والمهدي ليس في الصحيحين وضعّف ابن خلدون أخباره بينما رآها ابن حجر والسيوطي وغيرهما متضافرة", "زلزال وطوفان فقط", "المهدي فقط", "لا يذكر الحديث علامات"], "روى مسلم حديث حذيفة بن أسيد في عشر آيات: الدخان والدجال والدابة وطلوع الشمس من مغربها ونزول عيسى ويأجوج ومأجوج وثلاثة خسوف (بالمشرق والمغرب وجزيرة العرب) ونار تخرج من اليمن، وأخبار المهدي عند أبي داود والترمذي وغيرهما وانتقدها ابن خلدون في «المقدمة»، ورأى كثير من العلماء أنها متضافرة."] },

  { id: "xaq-037", s: "aqidah", g: 4, d: 7, t: ["sources", "khabar-wahid-aqida", "ahad-in-creed"], tr: ["comparative", "athari", "ashari", "maturidi"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; Ibn Qudāma, Rawḍat al-Nāẓir; al-Āmidī, al-Iḥkām; Ibn al-Qayyim, Mukhtaṣar al-Ṣawāʿiq al-Mursala",
    en: ["Is a single-narrator report (khabar al-āḥād) accepted in matters of creed, according to the traditions?", ["The Atharīs, with Aḥmad and the muḥaddithūn, accepted authentic āḥād reports in creed; many Ashʿarīs and Māturīdīs required certainty for fundamental matters and accepted āḥād for details, while the Muʿtazila rejected them", "All traditions rejected it", "All traditions accepted any report without condition", "None of the traditions discussed it"], "The question divides: the Atharīs hold that sound āḥād reports establish creed (as seen in Ibn al-Qayyim’s defence), and the Ashʿarīs and Māturīdīs divide matters of creed into those requiring a decisive proof (such as God’s existence and prophecy) and those that can rest on probable reports, though many accept them as binding on practice and belief in details. The Muʿtazila rejected āḥād for creed, requiring certainty."],
    de: ["Wird ein Einzelbericht (ḫabar al-āḥād) nach den Traditionen in Glaubensfragen angenommen?", ["Die Atharīten mit Aḥmad und den Muḥaddiṯūn nahmen authentische Āḥād-Berichte im Glauben an; viele Ašʿariten und Māturīditen verlangten Gewissheit für Grundfragen und nahmen Āḥād für Einzelheiten an, während die Muʿtazila sie ablehnten", "Alle Traditionen lehnten ihn ab", "Alle Traditionen nahmen jeden Bericht ohne Bedingung an", "Die Frage wurde in den Traditionen nie erörtert"], "Die Frage spaltet: Die Atharīten halten, dass gesunde Āḥād-Berichte den Glauben begründen (wie in Ibn al-Qayyims Verteidigung zu sehen), und die Ašʿariten und Māturīditen teilen Glaubensfragen in solche, die einen entscheidenden Beleg verlangen (wie Gottes Existenz und Prophetie), und solche, die auf wahrscheinlichen Berichten beruhen können, wobei viele sie für die Praxis und den Glauben im Einzelnen als bindend annehmen. Die Muʿtazila lehnten Āḥād für den Glauben ab und verlangten Gewissheit."],
    ar: ["هل يُقبل خبر الآحاد في العقيدة بحسب التقاليد العقدية؟", ["قبلت أهل الأثر مع أحمد والمحدثين أخبار الآحاد الصحيحة في العقيدة، ومعظم الأشاعرة والماتريدية اشترطوا اليقين في الأصول وقبلوه في التفاصيل ورده المعتزلة", "ردته كل التقاليد", "قبلته كل التقاليد بلا شرط", "لم تبحثه التقاليد"], "اختلفوا في المسألة: يرى أهل الأثر أن الآحاد الصحيحة تثبت بها العقيدة (كما في دفاع ابن القيم)، ويقسم الأشاعرة والماتريدية مسائل العقيدة إلى ما يتطلب دليلًا قاطعًا كوجود الله والنبوة وما يجوز بنائه على أخبار ظنية، مع قبول كثيرين لها ملزمة في العمل والاعتقاد في التفاصيل، ورد المعتزلة الآحاد في العقيدة اشتراطًا لليقين."] },

  { id: "xaq-038", s: "aqidah", g: 4, d: 6, t: ["istawa", "uluww", "athari-ashari"], tr: ["athari", "ashari", "comparative"], src: "Mālik as quoted in al-Bayhaqī, al-Asmāʾ wa-l-Ṣifāt; al-Dhahabī, al-ʿUluww li-l-ʿAliyy al-Ghaffār; Ibn al-Jawzī, Daf‘ Shubah al-Tashbīh; al-Ṭaḥāwī, al-ʿAqīda",
    en: ["What is the report attributed to Mālik ibn Anas about God’s ‘istiwāʾ’ above the Throne, and how did traditions use it?", ["That istiwāʾ is known, how is unknown, belief in it is obligatory and asking about it is an innovation; all the traditions cite it, with the Atharīs taking it as affirmation and the Ashʿarīs often as denial of the how and delegation of the meaning", "That God is in every place", "That the Throne is God", "That Mālik rejected the verse"], "A saying attributed to Mālik (and in some versions to Umm Salama and Rabīʿa) in answer to a question about the verse on istiwāʾ states that the istiwāʾ is not unknown, the how is not understood, faith in it is obligatory and the question is an innovation. The Atharīs read this as affirming the attribute without asking how; many Ashʿarīs read it as supporting delegation of the meaning; al-Bayhaqī and al-Dhahabī transmitted it in their works."],
    de: ["Welche Aussage wird Mālik ibn Anas über Gottes ‚istiwāʾ‘ über dem Thron zugeschrieben, und wie gebrauchten die Traditionen sie?", ["Dass der Istiwāʾ bekannt, das Wie unbekannt, der Glaube daran Pflicht und die Frage danach eine Neuerung ist; alle Traditionen zitieren sie, wobei die Atharīten sie als Bejahung und die Ašʿariten oft als Verneinung des Wie und Überlassung der Bedeutung nehmen", "Dass Gott an jedem Ort ist", "Dass der Thron Gott ist", "Dass Mālik den Vers ablehnte"], "Ein Mālik zugeschriebener Ausspruch (in manchen Fassungen auch Umm Salama und Rabīʿa) als Antwort auf eine Frage zum Vers über den Istiwāʾ besagt, der Istiwāʾ sei nicht unbekannt, das Wie nicht begreifbar, der Glaube daran Pflicht und die Frage Neuerung. Die Atharīten lesen dies als Bejahung des Attributs ohne Frage nach dem Wie; viele Ašʿariten lesen es als Stütze der Überlassung der Bedeutung; al-Baihaqī und aḏ-Ḏahabī überlieferten es in ihren Werken."],
    ar: ["ما المروي عن مالك بن أنس في استواء الله على العرش وكيف استعملته التقاليد؟", ["أن الاستواء معلوم والكيف مجهول والإيمان به واجب والسؤال عنه بدعة، وتنقله التقاليد كلها فيجعله أهل الأثر إثباتًا ويجعله الأشاعرة غالبًا نفيًا للكيف وتفويضًا للمعنى", "أن الله في كل مكان", "أن العرش هو الله", "أن مالكًا ردّ الآية"], "يُروى عن مالك (وفي بعض الروايات عن أم سلمة وربيعة) جوابًا لسؤال عن آية الاستواء أن الاستواء غير مجهول والكيف غير معقول والإيمان به واجب والسؤال عنه بدعة، ويقرأه أهل الأثر إثباتًا للصفة بلا سؤال عن الكيف ويقرأه كثير من الأشاعرة دعمًا للتفويض، وروى البيهقي والذهبي ذلك في كتبهما."] },

  { id: "xaq-039", s: "aqidah", g: 4, d: 7, t: ["rational-obligation", "fitrah", "prior-knowledge-of-god"], tr: ["comparative", "ashari", "maturidi", "athari"], src: "al-Māturīdī, Kitāb al-Tawḥīd; al-Ashʿarī, al-Lumaʿ; Ibn Taymiyya, Dar’ Taʿāruḍ al-ʿAql wa-l-Naql; al-Bukhārī, Ṣaḥīḥ, Kitāb al-janāʾiz (ḥadīth al-fiṭra)",
    en: ["Is knowing God obligatory by reason alone before revelation reaches, according to the traditions?", ["The Muʿtazila held that reason alone obliges knowledge of God; the Ashʿarīs held that obligation arises only through revelation; the Māturīdīs held that reason obliges knowing God though punishment depends on revelation; the Atharīs stressed the innate disposition (fiṭra) and the Prophetic report on it", "All traditions held that nothing is obligatory", "All traditions held that reason alone settles all law", "No tradition discussed it"], "The question of rational obligation (al-taḥsīn wa-l-taqbīḥ al-ʿaqliyyayn) divides: the Muʿtazila said reason knows good and evil and obliges knowing God; the Ashʿarīs said good and evil are known by revelation, so no obligation before it; the Māturīdīs gave reason a role in knowing God, although punishment awaits the message; the Atharīs spoke of fiṭra, citing the ḥadīth that every child is born upon the fiṭra."],
    de: ["Ist das Erkennen Gottes nach den Traditionen allein durch die Vernunft vor Eintreffen der Offenbarung Pflicht?", ["Die Muʿtazila hielten, die Vernunft allein verpflichte zur Erkenntnis Gottes; die Ašʿariten, die Verpflichtung entstehe nur durch Offenbarung; die Māturīditen, die Vernunft verpflichte zur Erkenntnis Gottes, die Strafe hänge aber von der Offenbarung ab; die Atharīten betonten die angeborene Anlage (fiṭra) und den prophetischen Bericht darüber", "Alle Traditionen hielten, nichts sei verpflichtend", "Alle Traditionen hielten, die Vernunft allein regle das ganze Recht", "Keine Tradition erörterte es"], "Die Frage der rationalen Verpflichtung (at-taḥsīn wa-t-taqbīḥ al-ʿaqliyyān) spaltet: Die Muʿtazila sagten, die Vernunft erkenne Gut und Böse und verpflichte zur Erkenntnis Gottes; die Ašʿariten, Gut und Böse würden durch Offenbarung erkannt, sodass es vorher keine Verpflichtung gebe; die Māturīditen gaben der Vernunft eine Rolle bei der Erkenntnis Gottes, obwohl die Strafe die Botschaft abwartet; die Atharīten sprachen von der Fiṭra und führten den Hadith an, jedes Kind werde auf der Fiṭra geboren."],
    ar: ["هل معرفة الله واجبة بالعقل وحده قبل بلوغ الوحي بحسب التقاليد العقدية؟", ["أوجب المعتزلة معرفة الله بالعقل وحده، وقال الأشاعرة لا وجوب إلا بالشرع، وقال الماتريدية يوجب العقل معرفة الله والعقاب موقوف على الرسالة، وأكد أهل الأثر الفطرة والحديث فيها", "قالت كل التقاليد لا شيء واجب", "قالت كل التقاليد إن العقل وحده يحكم الأحكام كلها", "لم تبحث تقاليد المسألة"], "يتصل خلاف التحسين والتقبيح العقليين: قال المعتزلة إن العقل يعرف الحسن والقبيح ويوجب معرفة الله، وقال الأشاعرة إن الحسن والقبح بالشرع فلا وجوب قبله، وجعل الماتريدية للعقل دورًا في معرفة الله مع توقف العقاب على بلوغ الرسالة، وتحدث أهل الأثر عن الفطرة محتجين بحديث «كل مولود يولد على الفطرة»."] },

  { id: "xaq-040", s: "aqidah", g: 4, d: 7, t: ["ahl-al-sunna", "definition", "firqa-najiyya"], tr: ["comparative", "sunni"], src: "al-Tirmidhī, Jāmiʿ, Kitāb al-īmān (ḥadīth iftirāq al-umma); al-Baghdādī, al-Farq bayna al-Firaq; al-Shāṭibī, al-Iʿtiṣām; Ibn Taymiyya, Majmūʿ al-Fatāwā",
    en: ["What is the discussion about the hadith of the community’s division into seventy-three groups?", ["The hadith is in al-Tirmidhī, Abū Dāwūd and Ibn Mājah and is graded ḥasan or ṣaḥīḥ by many, with differing wording on the saved group; scholars disagree on who is meant, with Atharīs, Ashʿarīs, Māturīdīs and others each identifying the saved group with themselves, while some stress it refers to the main body of the Muslims", "It is in the Quran only", "It was graded fabricated by every scholar", "It is reported only by al-Bukhārī"], "The hadith of division (Abū Dāwūd, al-Tirmidhī, Ibn Mājah) says the community will divide into seventy-three groups, all in the Fire except one (in some versions the one that follows what the Prophet and his Companions were upon, or the main body, al-jamāʿa). Some scholars (e.g. Ibn Ḥazm) weakened the addition about the Fire. Authors such as al-Baghdādī and al-Shāṭibī used the hadith, with each tradition applying it to itself, while others read it as a warning about method."],
    de: ["Was ist die Erörterung zum Hadith von der Spaltung der Gemeinschaft in dreiundsiebzig Gruppen?", ["Der Hadith steht bei at-Tirmiḏī, Abū Dāwūd und Ibn Māǧa und wird von vielen als ḥasan oder ṣaḥīḥ beurteilt, mit abweichendem Wortlaut zur geretteten Gruppe; die Gelehrten sind uneins, wer gemeint ist, wobei Atharīten, Ašʿariten, Māturīditen und andere die gerettete Gruppe jeweils mit sich identifizieren, während manche betonen, es meine die Hauptmasse der Muslime", "Er steht nur im Koran", "Er wurde von jedem Gelehrten als erfunden beurteilt", "Er wird nur von al-Buḫārī überliefert"], "Der Hadith von der Spaltung (Abū Dāwūd, at-Tirmiḏī, Ibn Māǧa) besagt, die Gemeinschaft werde sich in dreiundsiebzig Gruppen spalten, alle im Feuer außer einer (in manchen Fassungen die, die dem folgt, worauf der Prophet und seine Gefährten waren, oder die Hauptmasse, al-ǧamāʿa). Manche Gelehrte (z. B. Ibn Ḥazm) hielten den Zusatz über das Feuer für schwach. Autoren wie al-Baġdādī und aš-Šāṭibī gebrauchten den Hadith, wobei jede Tradition ihn auf sich selbst anwendet, während andere ihn als Warnung vor Methodenfehlern lesen."],
    ar: ["ما النقاش في حديث افتراق الأمة إلى ثلاث وسبعين فرقة؟", ["الحديث عند الترمذي وأبي داود وابن ماجه وحسّنه أو صححه كثيرون مع اختلاف الألفاظ في الفرقة الناجية، ويختلف العلماء فيمن المراد فيعيّن أهل الأثر والأشاعرة والماتريدية وغيرهم كلٌّ نفسه، ويرى بعضهم أنه السواد الأعظم من المسلمين", "هو في القرآن فقط", "حكم كل عالم بوضعه", "رواه البخاري وحده"], "حديث الافتراق (أبو داود والترمذي وابن ماجه) أن الأمة ستفترق ثلاثًا وسبعين فرقة كلها في النار إلا واحدة (وفي روايات: ما أنا عليه وأصحابي، أو الجماعة)، وضعّف بعض العلماء كابن حزم زيادة النار، واستعمله البغدادي والشاطبي وغيرهما مع تطبيق كل تقليد له على نفسه، بينما حمله آخرون تحذيرًا من المنهج."] },
];
